INSERT INTO `news` (`id`, `title`, `content`, `user_id`, `create_time`, `view_count`, `like_count`, `media_type`, `comment_count`, `collect_count`, `status`, `is_deleted`, `update_time`) VALUES
(1, '微服务拆分踩坑，随便聊聊', '前后端联调跑不通，最后发现是跨域配置写漏了一行，找了两个小时\n建议早点开始，最后一周才开始的话基本是在赌运气\n#微服务', 65, '2026-08-07 14:46:04', 172, 3, 1, 2, 0, 0, '0', '2026-08-07 15:35:04'),
(2, '今天的晚霞，说说你们那边', '沿着操场外圈走了一圈，风挺凉，穿短袖已经有点顶不住\n拍了十几张，只有这张勉强能发，其他全糊了', 72, '2026-08-07 16:39:26', 154, 2, 1, 0, 0, 0, '0', '2026-08-07 17:49:26'),
(3, '坚持一个月的变化，有点破防', '晚上九点的操场风很凉，跑完在跑道边坐着，感觉一天的疲惫都散了\n夜跑第一天，跑了三公里，配速七分半，腿有点酸但心情很好 #夜跑', 50, '2026-08-07 17:36:55', 166, 2, 1, 0, 0, 0, '0', NULL),
(4, '队友把我卖了，笑不活了', '双排的时候他全程在聊别的，报点报错两次，我直接闭麦\n建议找固定队友，随机匹配太考验心态', 86, '2026-08-07 23:53:44', 231, 4, 1, 8, 1, 0, '0', NULL),
(5, '十二点的食堂，笑不活了', '食堂的汤永远是温的，喝完更渴\n二楼最右边那个窗口的粉蒸肉是真的香，就是每次只剩一点点\n建议十一点半就去，人少菜全，就是要牺牲一节课的时间\n#干饭', 49, '2026-08-08 04:25:25', 121, 15, 1, 0, 1, 0, '0', NULL),
(6, '单机通关了，笑不活了', '单机的好处是不用等队友，坏处是通关之后有点空\n这游戏的解谜设计挺讲究，卡了我三次，每次想通都挺爽\n重玩一遍才发现前面埋了很多伏笔，第一遍完全没注意\n#单机游戏', 69, '2026-08-08 17:07:12', 326, 6, 1, 0, 0, 0, '0', NULL),
(7, '复习不完了，说说你们那边', '昨天通宵到三点，今天上课全程在飘，笔记写到一半变成了横线\n第一门考完感觉还行，选择题全靠直觉，问答题把能想到的都写了', 54, '2026-08-08 18:34:05', 282, 0, 2, 0, 0, 0, '0', NULL),
(8, '青轴真的吵，有点破防', '同样的轴体，不同键帽高度手感差别挺明显，这个之前完全没想过\n宿舍里建议红轴或者静音轴，青轴真的会得罪人\n键盘这种外设，适合自己的就是最好的，别人推荐只能参考', 49, '2026-08-09 01:59:06', 152, 7, 1, 4, 0, 0, '0', NULL),
(9, '自己拆机清灰，有点破防', '换硅脂要注意别涂太多，我第一次涂多了，温度反而高了两度\n加了一条内存，从八G到十六G，开几个网页终于不卡了\n工具一套三十块，比送修划算，前提是你敢动手\n#清灰', 86, '2026-08-09 07:53:09', 261, 5, 2, 1, 0, 0, '0', NULL),
(10, '单机通关了，随便聊聊', '这游戏的解谜设计挺讲究，卡了我三次，每次想通都挺爽\n重玩一遍才发现前面埋了很多伏笔，第一遍完全没注意\n剧情不算新鲜，但人物写得好，最后一个镜头我愣了很久 #单机游戏', 42, '2026-08-09 08:15:27', 168, 4, 2, 0, 0, 0, '0', NULL),
(11, '键帽换了之后，谁懂啊', '键盘这种外设，适合自己的就是最好的，别人推荐只能参考\n青轴声音太大，室友已经抗议两次，我准备换静音轴\n从薄膜换到机械，第一天打字速度反而变慢了，一周之后才习惯\n同样的轴体，不同键帽高度手感差别挺明显，这个之前完全没想过', 72, '2026-08-09 20:29:18', 288, 13, 2, 0, 3, 0, '0', NULL),
(12, '开学前买了电脑，在线等', '写代码其实不需要太高的配置，内存加到十六G比什么都管用\n预算五千左右，主要写代码和看视频，偶尔打游戏，在纠结轻薄本还是游戏本', 42, '2026-08-10 00:01:59', 308, 16, 1, 0, 2, 0, '0', NULL),
(13, '教学楼后面的落日，笑不活了', '手机拍出来比肉眼差远了，颜色压得很平，凑合看\n傍晚六点多从教学楼出来，整片天是橙红过渡到紫，我站着看了五分钟才想起拍照\n#晚霞', 72, '2026-08-10 03:29:24', 132, 5, 1, 0, 0, 0, '0', NULL),
(14, '开学前买了电脑，说说你们那边', '最后买了轻薄本，重量一点三公斤，通勤背着不累，就是风扇一开声音大\n预算五千左右，主要写代码和看视频，偶尔打游戏，在纠结轻薄本还是游戏本\n#笔记本', 61, '2026-08-10 18:13:10', 388, 29, 2, 0, 6, 0, '0', NULL),
(15, '宿舍网又卡了，在线等', '断线重连三次，第四次直接被判挂机，信誉分掉了不少\n晚上八点到十点，宿舍网必卡，延迟从三十跳到一百五，人物走两步退一步\n建议错峰，晚上十一点之后反而稳，可能是因为大家都去睡了\n开加速器能压到六十左右，就是每个月要交钱，学生党有点心疼', 69, '2026-08-10 21:28:41', 265, 2, 1, 2, 0, 0, '0', NULL),
(16, '一百多的耳机够用吗，谁懂啊', '自习室用降噪耳机效果挺明显，翻书声和键盘声基本听不到\n宿舍里耳机是必需品，不然你会听到所有你想不到的声音\n一百多的耳机日常够用，追求音质得加预算，但学生党没必要\n#降噪', 75, '2026-08-10 22:06:38', 91, 8, 1, 0, 2, 0, '0', '2026-08-10 23:20:38'),
(17, '今天这碗米粉，有点破防', '最近涨了一块，量倒是没变，也能接受\n早餐吃粉已经成习惯，一天不吃总觉得少点什么\n学校后门那家我吃了两年，老板记得我不要葱，加汤的时候会多给一勺\n外地朋友第一次吃可能受不了酸笋的味道，建议先少放一点 #桂林米粉', 83, '2026-08-11 00:51:43', 234, 11, 1, 0, 2, 0, '0', NULL),
(18, '复习不完了，有感而发', '老师说的重点和大家整理的重点完全不是一个东西，现在有五个版本在群里流传\n第一门考完感觉还行，选择题全靠直觉，问答题把能想到的都写了\n期末周正式开始，课表上还剩四门，我一门都没复习完', 17, '2026-08-11 03:11:22', 180, 2, 1, 1, 1, 0, '0', '2026-08-11 03:12:22'),
(19, '通勤两小时值得吗，有点破防', '实习第三周，主要在做接口联调和改 bug，代码量不大，但学到了不少规范\n每天通勤来回两小时，早上六点半出门，晚上八点到宿舍，人确实有点疲', 18, '2026-08-11 07:26:29', 292, 4, 2, 9, 0, 0, '0', NULL),
(20, '食堂是不是涨价了，在线等', '食堂的汤永远是温的，喝完更渴\n阿姨给我的肉明显比别人少，我怀疑是看我不顺眼，但我没说\n#食堂', 80, '2026-08-11 08:57:35', 206, 7, 1, 4, 2, 0, '0', NULL),
(21, '通宵自习警告，有点破防', '老师说的重点和大家整理的重点完全不是一个东西，现在有五个版本在群里流传\n复习效率最高的时候是考前两小时，其余时间都在整理桌面\n建议别通宵，第二天脑子是空的，我试过，代价很大', 42, '2026-08-11 17:56:56', 213, 1, 1, 4, 0, 0, '0', NULL),
(22, '秋招简历求看，随便聊聊', '投了三十家，已读的不到十家，回信两家，心态有点崩\n简历改了八遍，删掉了所有“熟悉”“了解”，改成具体做过什么，看着踏实多了\n建议找同学互看简历，自己看永远看不出问题\n#简历', 57, '2026-08-11 18:41:14', 69, 2, 1, 0, 0, 0, '0', NULL),
(23, '微服务拆分踩坑，笑不活了', '建议早点开始，最后一周才开始的话基本是在赌运气\n拆分微服务的时候最麻烦的是用户信息，内容服务要调用户服务，还要处理降级\n#课设', 43, '2026-08-11 23:04:55', 215, 11, 2, 1, 0, 0, '0', NULL),
(24, '凌晨的便利店，记录一下', '同样的水便利店比超市贵一块五，但胜在近，半夜也只能认了\n凌晨一点去楼下便利店，只有关东煮和泡面，收银小哥在打瞌睡\n#便利店', 71, '2026-08-12 04:11:05', 360, 15, 1, 1, 2, 0, '0', NULL),
(25, '操场边上的天空，随便聊聊', '手机拍出来比肉眼差远了，颜色压得很平，凑合看\n这个点最适合发呆，什么都不想干，也不想回宿舍\n梧桐叶开始黄了，路灯一亮，地上全是碎影子 #随手拍', 33, '2026-08-12 04:33:23', 314, 3, 2, 6, 2, 0, '0', NULL),
(26, '操场晚上人真多，有点破防', '坚持晨跑第五天，今天早上有雾，跑道尽头看不太清，跑起来倒挺舒服\n操场边上的自动售货机永远缺货，只有无糖茶，喝起来像草\n跑步别穿板鞋，我上周穿板鞋跑了三公里，脚底板疼了四天\n晚上八点的操场全是人，跑道内圈被散步的占了，跑快一点就得一直绕', 77, '2026-08-12 08:19:12', 41, 1, 2, 9, 0, 0, '0', NULL),
(27, '今天的晚霞，先记下来', '拍了十几张，只有这张勉强能发，其他全糊了\n傍晚六点多从教学楼出来，整片天是橙红过渡到紫，我站着看了五分钟才想起拍照\n手机拍出来比肉眼差远了，颜色压得很平，凑合看\n梧桐叶开始黄了，路灯一亮，地上全是碎影子', 54, '2026-08-12 13:32:46', 78, 2, 2, 0, 1, 0, '0', NULL),
(28, '今天这碗米粉，真的会谢', '外地朋友第一次吃可能受不了酸笋的味道，建议先少放一点\n最近涨了一块，量倒是没变，也能接受\n个人口味：卤菜粉加锅烧，酸豆角多放，辣椒少放，最后一定要加一勺卤水', 89, '2026-08-12 16:15:05', 220, 3, 1, 0, 1, 0, '0', '2026-08-12 16:26:05'),
(29, '二楼窗口的粉蒸肉，随便聊聊', '建议十一点半就去，人少菜全，就是要牺牲一节课的时间\n阿姨给我的肉明显比别人少，我怀疑是看我不顺眼，但我没说\n#食堂', 57, '2026-08-12 19:48:01', 64, 3, 2, 0, 1, 0, '0', NULL),
(30, '换了新鼠标垫，在线等', '折腾了一晚，桌面终于像样了，显示器抬高一点脖子舒服很多\n灯带贴在显示器后面，晚上关灯的时候氛围感确实有，就是有点晃眼\n毕业前最后一次折腾，之后这些东西要么带走要么卖，想着有点舍不得\n#桌面', 69, '2026-08-12 22:53:51', 200, 3, 1, 7, 0, 1, '0', '2026-08-12 23:48:51'),
(31, '硅脂换了之后，有点破防', '加了一条内存，从八G到十六G，开几个网页终于不卡了\n保修期内建议别自己拆，我就是拆完发现不保修了\n拆机前记得先断电拔电池，我第一次没拔，螺丝刀碰到主板闪了一下，吓死\n工具一套三十块，比送修划算，前提是你敢动手 #清灰', 55, '2026-08-13 01:38:14', 300, 14, 2, 1, 2, 0, '0', NULL),
(32, '单机通关了，求个建议', '这游戏的解谜设计挺讲究，卡了我三次，每次想通都挺爽\n单机的好处是不用等队友，坏处是通关之后有点空 #单机游戏', 77, '2026-08-13 03:13:39', 251, 0, 1, 0, 0, 0, '0', NULL),
(33, '这次应该能过，在线等', '四级第二次考，还是差了几分，听力部分实在跟不上\n英语这东西停一个月就废，别指望突击\n六级听力像在放rap，语速快还带口音，我只能抓关键词', 52, '2026-08-13 04:15:13', 193, 10, 1, 0, 0, 0, '0', NULL),
(34, '我们宿舍的绿萝活下来了，随便聊聊', '室友每天凌晨两点还在打游戏，键盘声一直响，我说了三次，他答应得好好的\n晚上十一点准时断电，我的电脑刚跑到一半，直接黑屏，作业没保存\n洗衣房四台机器坏了两个，剩下两个永远有人排队，我已经抱着衣服站了四十分钟', 87, '2026-08-13 06:50:56', 257, 7, 1, 11, 1, 0, '0', '2026-08-13 08:11:56'),
(35, '换了把键盘，先记下来', '换了套键帽，手感没变多少，但看着舒服，这钱花得有点虚\n同样的轴体，不同键帽高度手感差别挺明显，这个之前完全没想过\n从薄膜换到机械，第一天打字速度反而变慢了，一周之后才习惯', 77, '2026-08-14 01:43:40', 171, 7, 1, 0, 3, 1, '0', NULL),
(36, '四楼靠窗位又被占了，说说你们那边', '提醒一下，现在晚上十点半清场，别睡过头被保安叫醒\n占座的人一半不在，桌上堆着书和水杯，人不知道去哪了', 43, '2026-08-14 03:04:48', 155, 1, 2, 0, 1, 0, '0', NULL),
(37, '早八人今天的命是闹钟给的，在线等', '闹钟从六点四十响到七点十分，我才爬起来，刷牙的时候还在想要不要装病\n七点五十的校园很安静，只有保洁阿姨和几个和我一样狂奔的人\n秋天的早上真的起不来，被子一裹就不想动，感觉床有引力\n#校园日常', 85, '2026-08-14 07:43:31', 345, 5, 2, 4, 1, 0, '0', NULL),
(38, '又喝了一杯，谁懂啊', '校门口那家新店，第二杯半价，排了半个小时，喝完觉得不太值\n这周已经喝了四杯，钱包和体重都在抗议\n推荐加椰果不加珍珠，珍珠太顶，喝完一下午不想吃饭\n#续命', 72, '2026-08-14 09:19:53', 334, 12, 1, 6, 2, 0, '0', NULL),
(39, '食堂排队排到楼梯口，随便聊聊', '建议十一点半就去，人少菜全，就是要牺牲一节课的时间\n中午十二点十分到食堂，队伍已经排到楼梯拐角，前面大概四十个人\n阿姨给我的肉明显比别人少，我怀疑是看我不顺眼，但我没说 #食堂', 75, '2026-08-14 15:50:47', 292, 5, 1, 2, 2, 0, '0', '2026-08-14 16:00:47'),
(40, '十二点的食堂，在线等', '阿姨给我的肉明显比别人少，我怀疑是看我不顺眼，但我没说\n建议十一点半就去，人少菜全，就是要牺牲一节课的时间\n#食堂', 85, '2026-08-14 17:01:30', 255, 0, 2, 0, 0, 0, '0', '2026-08-14 17:03:30'),
(41, '今晚手感不错，人麻了', '刚刚那把在最后三十秒被人从背后偷了，我全程没听到脚步，回放看了三遍\n新手别急着冲，先把地图记熟，不然你会像我一样在出生点转圈\n摸到金的时候手都在抖，撤出来那一刻心跳一百二', 29, '2026-08-15 02:28:02', 83, 3, 2, 7, 1, 0, '0', NULL),
(42, '无糖真的不甜，说说你们那边', '我一般点三分糖去冰，甜度刚好，全糖真的齁\n推荐加椰果不加珍珠，珍珠太顶，喝完一下午不想吃饭 #奶茶', 45, '2026-08-15 18:46:06', 272, 29, 1, 0, 4, 0, '0', '2026-08-15 19:43:06'),
(43, '快递柜满了，记录一下', '我的快递被别人取走了，监控看了半天，最后是隔壁宿舍拿错，箱子已经拆了\n驿站阿姨已经认识我了，看到我就直接把我那个箱子拎出来，效率高得吓人\n#校园日常', 19, '2026-08-16 06:49:33', 761, 50, 1, 4, 11, 0, '0', NULL),
(44, '食堂是不是涨价了，随便聊聊', '建议十一点半就去，人少菜全，就是要牺牲一节课的时间\n今天打了三个菜一共十四块，感觉比上学期贵了两块，不知道是不是我记错\n#食堂', 34, '2026-08-16 07:26:04', 291, 1, 2, 0, 0, 0, '0', '2026-08-16 07:46:04'),
(45, '手游手感真不行，真的会谢', '建议配个散热背夹，几十块钱，效果比想象中好\n手机屏幕小，远处的人根本看不清，全靠猜', 69, '2026-08-16 23:38:33', 276, 11, 1, 3, 2, 0, '0', '2026-08-17 00:10:33'),
(46, '旧手机还能再战，有感而发', '旧手机留着当备用机，装个卡当热点，也算物尽其用\n拍照比想象中好，白天没问题，晚上还是有点糊，日常够用\n#数码', 42, '2026-08-17 02:50:31', 85, 5, 1, 2, 0, 0, '0', NULL),
(47, '二楼窗口的粉蒸肉，人麻了', '建议十一点半就去，人少菜全，就是要牺牲一节课的时间\n二楼最右边那个窗口的粉蒸肉是真的香，就是每次只剩一点点\n中午十二点十分到食堂，队伍已经排到楼梯拐角，前面大概四十个人', 56, '2026-08-17 05:36:09', 282, 2, 1, 0, 0, 0, '0', '2026-08-17 06:59:09'),
(48, '宿舍楼下那只狸花，在线等', '我买了一小袋猫粮，结果引来四只，最后那只橘的吃最多，还打我\n这只猫耳朵上有个缺口，估计以前打过架，现在混得挺开，谁给吃的跟谁走\n有同学给它搭了个纸箱窝，第二天被人扔了，气得在群里骂了半小时\n提醒一下，别喂太咸的东西，上次有人喂火腿肠，猫拉了两天肚子', 72, '2026-08-17 09:21:10', 465, 57, 1, 6, 12, 0, '0', NULL),
(49, '室友的作息我真的受不了，求个建议', '宿舍四个人共用一个插排，谁先插上谁有理\n室友每天凌晨两点还在打游戏，键盘声一直响，我说了三次，他答应得好好的 #断电', 86, '2026-08-17 13:11:35', 170, 3, 1, 0, 2, 0, '0', NULL),
(50, '入耳戴久了耳朵疼，有点破防', '自习室用降噪耳机效果挺明显，翻书声和键盘声基本听不到\n宿舍里耳机是必需品，不然你会听到所有你想不到的声音', 42, '2026-08-17 15:11:51', 63, 3, 2, 4, 1, 0, '0', NULL),
(51, '联调跑不通，说说你们那边', '建议早点开始，最后一周才开始的话基本是在赌运气\n课设终于跑起来了，五个服务加网关，启动顺序错了就各种 503，折腾了一晚上\n答辩 PPT 做完了，二十页，讲稿还没写，估计要练三四遍\n前后端联调跑不通，最后发现是跨域配置写漏了一行，找了两个小时', 49, '2026-08-17 17:12:59', 123, 2, 1, 2, 0, 0, '0', '2026-08-17 17:45:59'),
(52, '便利店的东西真贵，笑不活了', '关东煮的萝卜煮得很透，汤也好喝，就是有点贵，一串三块\n便利店是深夜唯一还亮着的地方，站在门口会有种奇怪的安全感\n半夜饿了不想出门，翻遍宿舍只有一包泡面和一袋饼干\n换老板之后关东煮味道变了，汤淡了不少，我去得少了', 43, '2026-08-17 18:26:22', 257, 15, 1, 0, 3, 0, '0', NULL),
(53, '打球扭到脚了，谁懂啊', '体测通知下来了，引体向上我一个都做不了，已经开始焦虑\n跑步别穿板鞋，我上周穿板鞋跑了三公里，脚底板疼了四天\n#夜跑', 19, '2026-08-17 20:13:49', 305, 5, 1, 0, 1, 0, '0', NULL),
(54, '四级又没过，真的会谢', '六级听力像在放rap，语速快还带口音，我只能抓关键词\n四级第二次考，还是差了几分，听力部分实在跟不上', 43, '2026-08-17 22:19:02', 94, 0, 1, 36, 0, 0, '0', NULL),
(55, '我们宿舍的绿萝活下来了，求个建议', '晚上十一点准时断电，我的电脑刚跑到一半，直接黑屏，作业没保存\n宿舍四个人共用一个插排，谁先插上谁有理\n洗衣房四台机器坏了两个，剩下两个永远有人排队，我已经抱着衣服站了四十分钟', 33, '2026-08-18 01:47:05', 489, 29, 1, 1, 7, 0, '0', NULL),
(56, '排位又连跪，求个建议', '摸到金的时候手都在抖，撤出来那一刻心跳一百二\n新手别急着冲，先把地图记熟，不然你会像我一样在出生点转圈\n排位连跪五把，队友全程各玩各的，我索性关麦自己打\n刚刚那把在最后三十秒被人从背后偷了，我全程没听到脚步，回放看了三遍\n#排位', 39, '2026-08-18 16:24:41', 204, 0, 2, 0, 0, 0, '0', '2026-08-18 17:43:41'),
(57, '取个快递像赶集，在线等', '今天寄一个两公斤的件，被收了十二块，我当场沉默\n下课去快递站，前面排了三十多个人，队伍拐了两个弯\n双十一前后建议错峰，晚上九点去人最少，就是得摸黑找箱子 #快递', 54, '2026-08-18 22:17:38', 60, 2, 1, 15, 0, 0, '0', '2026-08-18 22:31:38'),
(58, '晨跑第五天，笑不活了', '体测通知下来了，引体向上我一个都做不了，已经开始焦虑\n打球的时候踩到别人脚，脚踝肿了一圈，冰敷完还是很疼，明天估计得去医院\n#操场', 23, '2026-08-19 02:26:18', 111, 3, 2, 3, 2, 1, '0', NULL),
(59, '跑道上的雾，随便聊聊', '跑步别穿板鞋，我上周穿板鞋跑了三公里，脚底板疼了四天\n坚持晨跑第五天，今天早上有雾，跑道尽头看不太清，跑起来倒挺舒服', 87, '2026-08-19 05:32:42', 132, 11, 1, 8, 3, 0, '0', '2026-08-19 06:40:42'),
(60, '米粉又涨价了，谁懂啊', '外地朋友第一次吃可能受不了酸笋的味道，建议先少放一点\n最近涨了一块，量倒是没变，也能接受\n个人口味：卤菜粉加锅烧，酸豆角多放，辣椒少放，最后一定要加一勺卤水\n早餐吃粉已经成习惯，一天不吃总觉得少点什么\n#桂林米粉', 82, '2026-08-19 06:37:57', 268, 4, 1, 0, 1, 0, '0', NULL),
(61, '宿舍楼下的雨，随便聊聊（386）', '晚上十一点准时断电，我的电脑刚跑到一半，直接黑屏，作业没保存\n昨晚下大雨，从窗户往外看，路灯把雨照得像在下雪，还挺好看\n洗衣房四台机器坏了两个，剩下两个永远有人排队，我已经抱着衣服站了四十分钟\n#宿舍生活', 77, '2026-08-19 23:26:37', 263, 18, 1, 13, 3, 0, '0', NULL),
(62, '通关二十小时，真的会谢', '重玩一遍才发现前面埋了很多伏笔，第一遍完全没注意\n剧情不算新鲜，但人物写得好，最后一个镜头我愣了很久\n这游戏的解谜设计挺讲究，卡了我三次，每次想通都挺爽\n单机的好处是不用等队友，坏处是通关之后有点空', 57, '2026-08-20 03:34:55', 237, 2, 1, 0, 1, 0, '0', NULL),
(63, '联调跑不通，真的会谢', '前后端联调跑不通，最后发现是跨域配置写漏了一行，找了两个小时\n课设终于跑起来了，五个服务加网关，启动顺序错了就各种 503，折腾了一晚上\n#课设', 72, '2026-08-20 05:55:33', 143, 5, 1, 12, 2, 0, '0', '2026-08-20 06:00:33'),
(64, '自习到闭馆，有点破防', '我一般坐三楼，人少，缺点是空调太冷，得带件外套\n今天硬坐了两个小时，效率还行，至少把昨天的实验报告写完了\n占座的人一半不在，桌上堆着书和水杯，人不知道去哪了 #自习', 49, '2026-08-20 10:19:51', 328, 5, 2, 0, 1, 0, '0', NULL),
(65, '寄快递被收了十二块，有点破防', '我的快递被别人取走了，监控看了半天，最后是隔壁宿舍拿错，箱子已经拆了\n驿站阿姨已经认识我了，看到我就直接把我那个箱子拎出来，效率高得吓人\n下课去快递站，前面排了三十多个人，队伍拐了两个弯 #校园日常', 36, '2026-08-20 14:48:44', 59, 2, 2, 2, 0, 0, '0', '2026-08-20 15:51:44'),
(66, '手机上也能玩，说说你们那边', '手机屏幕小，远处的人根本看不清，全靠猜\n手机上操作确实别扭，瞄准全靠手指，打了两把就放弃了\n#通勤', 54, '2026-08-22 00:46:47', 230, 3, 2, 18, 0, 0, '0', NULL),
(67, '八股文背不完，说说你们那边', '二面挂在场景题上，问我并发下怎么保证幂等，我只答了一半\n面试被问到项目里为什么用 Redis，我讲了一堆缓存，他说那不加行不行，我卡住了\n八股文真的背不完，昨天背的今天忘，感觉在跟自己对抗\n建议面试前把项目里每个技术选型的原因想清楚，这个比背题重要', 50, '2026-08-22 05:27:25', 79, 1, 1, 7, 0, 0, '0', '2026-08-22 06:46:25'),
(68, '打游戏必须开加速器，谁懂啊', '断线重连三次，第四次直接被判挂机，信誉分掉了不少\n建议错峰，晚上十一点之后反而稳，可能是因为大家都去睡了', 45, '2026-08-22 06:57:58', 178, 4, 1, 0, 0, 0, '1', '2026-08-22 07:04:58'),
(69, '期末周的第一天，谁懂啊', '昨天通宵到三点，今天上课全程在飘，笔记写到一半变成了横线\n第一门考完感觉还行，选择题全靠直觉，问答题把能想到的都写了\n老师说的重点和大家整理的重点完全不是一个东西，现在有五个版本在群里流传\n期末周正式开始，课表上还剩四门，我一门都没复习完', 52, '2026-08-23 02:43:04', 234, 2, 2, 0, 0, 0, '0', NULL),
(70, '要不要二战，有感而发', '建议每天留一小时运动，不然到后期身体先垮\n每天六点半起，晚上十一点回，中间有效学习时间大概七个小时，剩下都在走神\n自习室里大家都很安静，偶尔有人叹气，那种氛围挺压抑也挺鼓励', 71, '2026-08-23 04:24:25', 161, 6, 2, 0, 2, 0, '0', '2026-08-23 04:35:25'),
(71, '室友的作息我真的受不了，笑不活了', '昨晚下大雨，从窗户往外看，路灯把雨照得像在下雪，还挺好看\n隔壁宿舍搬走了，留下一股泡面味，三天没散\n#断电', 61, '2026-08-23 08:36:24', 138, 1, 2, 0, 0, 0, '0', NULL),
(72, '通宵自习警告，说说你们那边', '期末周正式开始，课表上还剩四门，我一门都没复习完\n第一门考完感觉还行，选择题全靠直觉，问答题把能想到的都写了\n建议别通宵，第二天脑子是空的，我试过，代价很大\n复习效率最高的时候是考前两小时，其余时间都在整理桌面\n#期末周', 69, '2026-08-24 05:23:40', 213, 6, 1, 3, 0, 0, '0', NULL),
(73, '躺床上打了两小时，随便聊聊', '建议配个散热背夹，几十块钱，效果比想象中好\n通勤路上打一把挺解压，就是信号不稳，地铁里经常掉线\n躺床上打了两小时，手腕酸得不行，还是得坐着玩', 19, '2026-08-24 08:58:37', 127, 5, 1, 1, 0, 0, '0', NULL),
(74, '便利店的东西真贵，记录一下', '关东煮的萝卜煮得很透，汤也好喝，就是有点贵，一串三块\n便利店是深夜唯一还亮着的地方，站在门口会有种奇怪的安全感\n半夜饿了不想出门，翻遍宿舍只有一包泡面和一袋饼干', 78, '2026-08-24 15:34:00', 46, 2, 1, 2, 1, 0, '0', NULL),
(75, '今天又喂了猫，说说你们那边', '这只猫耳朵上有个缺口，估计以前打过架，现在混得挺开，谁给吃的跟谁走\n有同学给它搭了个纸箱窝，第二天被人扔了，气得在群里骂了半小时 #校园猫', 77, '2026-08-24 21:40:42', 305, 30, 2, 18, 7, 0, '0', '2026-08-24 22:04:42'),
(76, '四楼靠窗位又被占了，随便聊聊', '今天硬坐了两个小时，效率还行，至少把昨天的实验报告写完了\n提醒一下，现在晚上十点半清场，别睡过头被保安叫醒\n占座的人一半不在，桌上堆着书和水杯，人不知道去哪了', 43, '2026-08-25 06:02:13', 240, 15, 1, 12, 3, 0, '0', NULL),
(77, '无糖真的不甜，随便聊聊', '校门口那家新店，第二杯半价，排了半个小时，喝完觉得不太值\n我一般点三分糖去冰，甜度刚好，全糖真的齁\n无糖选项其实是少糖，喝起来还是有甜味，不过热量确实低一些\n奶茶这东西，喝的时候快乐，喝完有点后悔，第二天还是想喝\n#奶茶', 55, '2026-08-25 06:11:04', 134, 0, 1, 0, 0, 0, '0', NULL),
(78, '面试被问懵了，求个建议', '八股文真的背不完，昨天背的今天忘，感觉在跟自己对抗\n建议面试前把项目里每个技术选型的原因想清楚，这个比背题重要\n面试被问到项目里为什么用 Redis，我讲了一堆缓存，他说那不加行不行，我卡住了', 17, '2026-08-25 06:24:41', 378, 13, 1, 12, 2, 0, '0', '2026-08-25 06:44:41'),
(79, '猫比我受欢迎，记录一下', '我买了一小袋猫粮，结果引来四只，最后那只橘的吃最多，还打我\n它今天又在我书包上睡了一觉，毛沾了一书包，我也没舍得赶 #撸猫', 77, '2026-08-25 15:37:45', 238, 7, 1, 3, 0, 0, '0', '2026-08-25 17:03:45'),
(80, '躺床上打了两小时，有感而发', '手机上操作确实别扭，瞄准全靠手指，打了两把就放弃了\n手机玩这类游戏发热很厉害，玩十分钟就烫手，还会掉帧 #手游', 43, '2026-08-26 01:16:07', 245, 2, 1, 1, 2, 0, '0', NULL),
(81, '答辩PPT做完了，随便聊聊', '建议早点开始，最后一周才开始的话基本是在赌运气\n答辩 PPT 做完了，二十页，讲稿还没写，估计要练三四遍\n#微服务', 94, '2026-08-26 07:55:09', 164, 7, 1, 2, 1, 0, '0', NULL),
(82, '新窗口排队，有感而发', '那个新出的凉拌菜别点，醋放太多，吃两口就腻\n三楼新开了一个窗口，卖砂锅和炒饭，今天试了砂锅饭，量足味道也还行', 45, '2026-08-26 08:04:59', 276, 19, 1, 7, 3, 0, '0', NULL),
(83, '秋招简历求看，真的会谢', '项目只有一个课设，写出来总觉得单薄，不知道要不要包装一下\n简历改了八遍，删掉了所有“熟悉”“了解”，改成具体做过什么，看着踏实多了\n投了三十家，已读的不到十家，回信两家，心态有点崩 #秋招', 61, '2026-08-26 18:43:51', 298, 15, 1, 11, 4, 0, '0', NULL),
(84, '手机拍照对比，求个建议', '新机续航确实好，中度使用能撑一天半，充电也快，半小时到七成\n旧手机留着当备用机，装个卡当热点，也算物尽其用\n拍照比想象中好，白天没问题，晚上还是有点糊，日常够用', 28, '2026-08-26 19:35:26', 287, 1, 2, 0, 1, 0, '0', '2026-08-26 20:12:26'),
(85, '秋招简历求看，求个建议', '建议找同学互看简历，自己看永远看不出问题\n投了三十家，已读的不到十家，回信两家，心态有点崩', 72, '2026-08-26 19:57:02', 125, 8, 1, 3, 0, 0, '0', NULL),
(86, '今天这个菜不错，求个建议', '三楼新开了一个窗口，卖砂锅和炒饭，今天试了砂锅饭，量足味道也还行\n隐藏吃法是打一份白饭加两块钱的蒸蛋，再要一勺免费的汤，一共不到五块', 82, '2026-08-26 20:16:57', 271, 2, 2, 2, 0, 0, '0', NULL),
(87, '二楼窗口的粉蒸肉，在线等', '二楼最右边那个窗口的粉蒸肉是真的香，就是每次只剩一点点\n食堂的汤永远是温的，喝完更渴', 43, '2026-08-26 21:31:47', 191, 6, 2, 1, 0, 0, '0', NULL),
(88, '复习进度汇报，真的会谢', '建议每天留一小时运动，不然到后期身体先垮\n最近一直在想如果没考上怎么办，家里希望我再来一年，我自己有点犹豫\n倒计时五十天，专业课还有两章没背，英语真题做到第三遍还是在错同一类题 #考研', 69, '2026-08-26 22:20:02', 443, 32, 2, 0, 9, 0, '0', NULL),
(89, '买手机别冲动，在线等', '拍照比想象中好，白天没问题，晚上还是有点糊，日常够用\n建议别在首发的时候买，等两个月价格能下来不少\n买之前先去实体店摸一下，手感和重量网上看不出来\n用三年的旧手机终于换了，主要是电池不行，一天要充两次', 49, '2026-08-27 06:51:12', 168, 10, 2, 18, 0, 0, '0', NULL),
(90, '这套外设值不值，说说你们那边', '说真的，外设对水平提升有限，但心情提升很大\n折腾了一晚，桌面终于像样了，显示器抬高一点脖子舒服很多\n灯带贴在显示器后面，晚上关灯的时候氛围感确实有，就是有点晃眼', 22, '2026-08-27 07:34:06', 43, 1, 1, 24, 0, 0, '0', NULL),
(91, '打球扭到脚了，说说你们那边', '坚持晨跑第五天，今天早上有雾，跑道尽头看不太清，跑起来倒挺舒服\n跑步别穿板鞋，我上周穿板鞋跑了三公里，脚底板疼了四天\n体测通知下来了，引体向上我一个都做不了，已经开始焦虑', 23, '2026-08-27 07:54:42', 261, 4, 2, 1, 1, 0, '0', NULL),
(92, '加卤蛋还是加锅烧，在线等', '个人口味：卤菜粉加锅烧，酸豆角多放，辣椒少放，最后一定要加一勺卤水\n今天这碗加了锅烧和卤蛋，一共十一块，汤头够味，酸笋放得刚好', 46, '2026-08-27 23:13:35', 97, 4, 1, 16, 1, 0, '0', '2026-08-28 00:15:35'),
(93, '食堂是不是涨价了，真的会谢', '二楼最右边那个窗口的粉蒸肉是真的香，就是每次只剩一点点\n建议十一点半就去，人少菜全，就是要牺牲一节课的时间 #食堂', 25, '2026-08-28 08:02:34', 277, 6, 2, 9, 2, 0, '0', '2026-08-28 08:50:34'),
(94, '猫比我受欢迎，求个建议', '有同学给它搭了个纸箱窝，第二天被人扔了，气得在群里骂了半小时\n宿舍楼下那只狸花今天蹲在窗台上晒太阳，我蹲下来它就往我腿边蹭\n它今天又在我书包上睡了一觉，毛沾了一书包，我也没舍得赶 #撸猫', 54, '2026-08-28 15:32:49', 240, 4, 2, 0, 0, 0, '0', '2026-08-28 16:27:49'),
(95, '楼下便利店换老板了，求个建议', '凌晨一点去楼下便利店，只有关东煮和泡面，收银小哥在打瞌睡\n关东煮的萝卜煮得很透，汤也好喝，就是有点贵，一串三块', 43, '2026-08-29 02:06:21', 184, 5, 2, 0, 1, 0, '0', '2026-08-29 03:19:21'),
(96, '项目怎么写才不虚，谁懂啊', '实习经历是硬门槛，没有的话就把课设做深，至少能讲清楚\n项目只有一个课设，写出来总觉得单薄，不知道要不要包装一下\n写项目建议按“问题—做法—结果”写，别只堆技术名词，面试官一问就露', 87, '2026-08-29 06:40:59', 118, 5, 2, 5, 1, 0, '0', NULL),
(97, '坚持一个月的变化，说说你们那边', '跑步确实会上瘾，一天不跑就难受，但膝盖也开始提醒我别太猛\n夜跑第一天，跑了三公里，配速七分半，腿有点酸但心情很好\n晚上九点的操场风很凉，跑完在跑道边坐着，感觉一天的疲惫都散了', 54, '2026-08-29 08:28:15', 126, 1, 2, 21, 0, 0, '0', '2026-08-29 09:30:15'),
(98, '奶茶店排队半小时，求个建议', '校门口那家新店，第二杯半价，排了半个小时，喝完觉得不太值\n这周已经喝了四杯，钱包和体重都在抗议\n#续命', 71, '2026-08-29 14:42:13', 378, 24, 1, 5, 1, 0, '0', '2026-08-29 16:02:13'),
(99, '宿舍楼下的雨，有点破防', '宿舍四个人共用一个插排，谁先插上谁有理\n隔壁宿舍搬走了，留下一股泡面味，三天没散\n昨晚下大雨，从窗户往外看，路灯把雨照得像在下雪，还挺好看', 72, '2026-08-29 15:49:42', 223, 11, 2, 0, 1, 1, '0', NULL),
(100, '四楼靠窗位又被占了，真的会谢', '闭馆音乐一响，整层楼同时开始收东西，那场面挺壮观\n今天硬坐了两个小时，效率还行，至少把昨天的实验报告写完了\n占座的人一半不在，桌上堆着书和水杯，人不知道去哪了', 67, '2026-08-29 18:51:44', 303, 1, 2, 2, 0, 0, '0', '2026-08-29 19:28:44'),
(101, '青轴真的吵，先记下来', '换了套键帽，手感没变多少，但看着舒服，这钱花得有点虚\n从薄膜换到机械，第一天打字速度反而变慢了，一周之后才习惯\n宿舍里建议红轴或者静音轴，青轴真的会得罪人', 83, '2026-08-29 22:05:01', 272, 2, 1, 2, 0, 0, '0', NULL),
(102, '图书馆四楼又满了，先记下来', '我一般坐三楼，人少，缺点是空调太冷，得带件外套\n占座的人一半不在，桌上堆着书和水杯，人不知道去哪了\n今天硬坐了两个小时，效率还行，至少把昨天的实验报告写完了\n#图书馆', 23, '2026-08-30 00:09:54', 316, 5, 2, 0, 0, 1, '0', NULL),
(103, '宿舍今晚又断电了，说说你们那边', '室友每天凌晨两点还在打游戏，键盘声一直响，我说了三次，他答应得好好的\n晚上十一点准时断电，我的电脑刚跑到一半，直接黑屏，作业没保存\n隔壁宿舍搬走了，留下一股泡面味，三天没散\n宿舍四个人共用一个插排，谁先插上谁有理 #断电', 87, '2026-08-30 04:28:19', 189, 1, 1, 10, 0, 0, '0', '2026-08-30 05:25:19'),
(104, '这次应该能过，记录一下', '六级听力像在放rap，语速快还带口音，我只能抓关键词\n四级建议先做真题，把题型摸熟，比背单词提分快', 43, '2026-08-30 17:03:01', 175, 7, 2, 6, 1, 0, '0', NULL),
(105, '快递站又排长队，谁懂啊', '下课去快递站，前面排了三十多个人，队伍拐了两个弯\n我的快递被别人取走了，监控看了半天，最后是隔壁宿舍拿错，箱子已经拆了 #校园日常', 47, '2026-08-30 18:30:43', 158, 4, 2, 3, 1, 0, '0', NULL),
(106, '食堂排队排到楼梯口，谁懂啊', '食堂的汤永远是温的，喝完更渴\n中午十二点十分到食堂，队伍已经排到楼梯拐角，前面大概四十个人\n今天打了三个菜一共十四块，感觉比上学期贵了两块，不知道是不是我记错\n#食堂', 43, '2026-08-30 22:02:01', 355, 7, 1, 7, 2, 0, '0', NULL),
(107, '操场边上的天空，有感而发', '手机拍出来比肉眼差远了，颜色压得很平，凑合看\n拍了十几张，只有这张勉强能发，其他全糊了\n#随手拍', 23, '2026-08-31 04:03:51', 107, 8, 1, 2, 1, 0, '0', NULL),
(108, '秋天的早上真起不来，人麻了', '秋天的早上真的起不来，被子一裹就不想动，感觉床有引力\n今天差点迟到，进门的时候老师已经在讲第二页了，我从前门走到最后一排，全程被看着\n早八最痛苦的不是上课，是要在前一晚十二点前睡着\n#早八人', 55, '2026-08-31 17:33:49', 263, 1, 1, 0, 0, 0, '0', NULL),
(109, '开学前买了电脑，先记下来', '别信“全新未拆”的低价，八成是翻新，这个坑我踩过\n写代码其实不需要太高的配置，内存加到十六G比什么都管用', 69, '2026-08-31 19:31:22', 207, 5, 2, 2, 1, 0, '0', NULL),
(110, '操场边上的天空，在线等', '傍晚六点多从教学楼出来，整片天是橙红过渡到紫，我站着看了五分钟才想起拍照\n拍了十几张，只有这张勉强能发，其他全糊了\n#随手拍', 52, '2026-09-01 01:39:15', 282, 7, 2, 0, 4, 0, '0', NULL),
(111, '打饭阿姨的手到底抖不抖，真的会谢', '今天打了三个菜一共十四块，感觉比上学期贵了两块，不知道是不是我记错\n食堂的汤永远是温的，喝完更渴', 77, '2026-09-01 03:39:41', 142, 7, 1, 0, 2, 0, '0', NULL),
(112, '手机发热严重，有点破防', '建议配个散热背夹，几十块钱，效果比想象中好\n手机屏幕小，远处的人根本看不清，全靠猜\n手机玩这类游戏发热很厉害，玩十分钟就烫手，还会掉帧', 52, '2026-09-01 19:38:09', 189, 5, 1, 6, 1, 0, '0', NULL),
(113, '取个快递像赶集，有点破防', '今天寄一个两公斤的件，被收了十二块，我当场沉默\n双十一前后建议错峰，晚上九点去人最少，就是得摸黑找箱子\n快递柜全满，只能放驿站，结果驿站六点半就关门，我下课赶过去刚好关灯', 81, '2026-09-01 20:56:54', 288, 2, 2, 0, 2, 0, '0', '2026-09-01 21:28:54'),
(114, '食堂排队排到楼梯口，先记下来（370）', '食堂的汤永远是温的，喝完更渴\n建议十一点半就去，人少菜全，就是要牺牲一节课的时间\n中午十二点十分到食堂，队伍已经排到楼梯拐角，前面大概四十个人', 33, '2026-09-01 23:18:30', 308, 5, 1, 9, 1, 0, '0', NULL),
(115, '快递柜满了，真的会谢', '快递柜全满，只能放驿站，结果驿站六点半就关门，我下课赶过去刚好关灯\n今天寄一个两公斤的件，被收了十二块，我当场沉默\n下课去快递站，前面排了三十多个人，队伍拐了两个弯', 57, '2026-09-02 03:56:23', 123, 0, 1, 10, 0, 0, '0', '2026-09-02 05:14:23'),
(116, '寄快递被收了十二块，说说你们那边', '下课去快递站，前面排了三十多个人，队伍拐了两个弯\n我的快递被别人取走了，监控看了半天，最后是隔壁宿舍拿错，箱子已经拆了\n今天寄一个两公斤的件，被收了十二块，我当场沉默\n双十一前后建议错峰，晚上九点去人最少，就是得摸黑找箱子\n#校园日常', 40, '2026-09-02 06:40:05', 175, 2, 1, 0, 0, 0, '0', NULL),
(117, '食堂排队排到楼梯口，求个建议（349）', '阿姨给我的肉明显比别人少，我怀疑是看我不顺眼，但我没说\n食堂的汤永远是温的，喝完更渴 #食堂', 54, '2026-09-02 07:02:27', 269, 9, 1, 0, 0, 1, '0', NULL),
(118, '晨跑第五天，在线等', '打球的时候踩到别人脚，脚踝肿了一圈，冰敷完还是很疼，明天估计得去医院\n跑步别穿板鞋，我上周穿板鞋跑了三公里，脚底板疼了四天\n坚持晨跑第五天，今天早上有雾，跑道尽头看不太清，跑起来倒挺舒服', 53, '2026-09-02 07:49:46', 264, 2, 1, 0, 1, 0, '0', NULL),
(119, '这个剧情我哭了，人麻了', '重玩一遍才发现前面埋了很多伏笔，第一遍完全没注意\n剧情不算新鲜，但人物写得好，最后一个镜头我愣了很久\n断断续续玩了二十多个小时，昨晚终于通关，结局那段我看了两遍\n#剧情', 77, '2026-09-02 16:55:32', 206, 1, 1, 1, 0, 0, '0', NULL),
(120, '桂林米粉哪家强，记录一下', '今天这碗加了锅烧和卤蛋，一共十一块，汤头够味，酸笋放得刚好\n外地朋友第一次吃可能受不了酸笋的味道，建议先少放一点\n个人口味：卤菜粉加锅烧，酸豆角多放，辣椒少放，最后一定要加一勺卤水', 71, '2026-09-02 18:07:58', 371, 9, 2, 0, 1, 0, '0', '2026-09-02 19:26:58'),
(121, '考研人的一天，求个建议', '倒计时五十天，专业课还有两章没背，英语真题做到第三遍还是在错同一类题\n建议每天留一小时运动，不然到后期身体先垮 #自习', 42, '2026-09-02 20:53:46', 140, 7, 1, 11, 1, 1, '0', NULL),
(122, '专业课背不完，记录一下', '每天六点半起，晚上十一点回，中间有效学习时间大概七个小时，剩下都在走神\n最近一直在想如果没考上怎么办，家里希望我再来一年，我自己有点犹豫\n专业课的背诵量比想象中大，第一遍背完感觉什么都没记住 #考研', 33, '2026-09-02 20:54:06', 228, 14, 2, 0, 2, 0, '0', '2026-09-02 21:26:06'),
(123, '加装内存条，求个建议', '风扇声音大得像起飞，拆开一看全是灰，清了之后安静不少\n换硅脂要注意别涂太多，我第一次涂多了，温度反而高了两度\n保修期内建议别自己拆，我就是拆完发现不保修了\n加了一条内存，从八G到十六G，开几个网页终于不卡了\n#拆机', 45, '2026-09-02 22:26:38', 227, 0, 1, 0, 0, 0, '0', '2026-09-02 23:04:38'),
(124, '队友把我卖了，先记下来', '建议找固定队友，随机匹配太考验心态\n这游戏真的需要沟通，但有些人的沟通就是指挥别人', 24, '2026-09-03 00:49:17', 304, 4, 1, 0, 0, 0, '0', NULL),
(125, '食堂排队排到楼梯口，记录一下', '阿姨给我的肉明显比别人少，我怀疑是看我不顺眼，但我没说\n建议十一点半就去，人少菜全，就是要牺牲一节课的时间', 72, '2026-09-03 01:20:36', 343, 21, 1, 0, 5, 0, '0', '2026-09-03 02:41:36'),
(126, '操场边上的天空，先记下来', '拍了十几张，只有这张勉强能发，其他全糊了\n梧桐叶开始黄了，路灯一亮，地上全是碎影子', 87, '2026-09-03 06:08:18', 108, 1, 1, 0, 0, 0, '0', '2026-09-03 07:18:18'),
(127, '这次应该能过，先记下来', '这次考前做了五套真题，感觉比上次稳，希望能过\n四级第二次考，还是差了几分，听力部分实在跟不上 #英语', 50, '2026-09-03 06:18:00', 252, 0, 1, 1, 0, 0, '0', NULL),
(128, '八股文背不完，有点破防', '一面感觉一般，手撕代码写出来了但边界没处理好，居然过了\n面试被问到项目里为什么用 Redis，我讲了一堆缓存，他说那不加行不行，我卡住了\n八股文真的背不完，昨天背的今天忘，感觉在跟自己对抗 #面试', 61, '2026-09-03 19:12:52', 158, 6, 1, 0, 1, 0, '0', '2026-09-03 19:57:52'),
(129, '考完第一门，先记下来', '老师说的重点和大家整理的重点完全不是一个东西，现在有五个版本在群里流传\n第一门考完感觉还行，选择题全靠直觉，问答题把能想到的都写了\n#复习', 54, '2026-09-03 22:57:57', 256, 8, 2, 3, 1, 0, '0', '2026-09-03 23:39:57'),
(130, '下午四点的图书馆，有感而发', '今天硬坐了两个小时，效率还行，至少把昨天的实验报告写完了\n我一般坐三楼，人少，缺点是空调太冷，得带件外套\n提醒一下，现在晚上十点半清场，别睡过头被保安叫醒\n下午两点去图书馆，四楼靠窗的位置全没了，只剩墙角一个没插座的位置\n#自习', 83, '2026-09-04 08:26:41', 78, 1, 1, 3, 0, 0, '0', '2026-09-04 08:59:41'),
(131, '考研人的一天，记录一下', '专业课的背诵量比想象中大，第一遍背完感觉什么都没记住\n最近一直在想如果没考上怎么办，家里希望我再来一年，我自己有点犹豫\n倒计时五十天，专业课还有两章没背，英语真题做到第三遍还是在错同一类题\n#自习', 87, '2026-09-04 09:20:10', 318, 5, 2, 0, 0, 0, '0', NULL),
(132, '手机发热严重，人麻了（338）', '建议配个散热背夹，几十块钱，效果比想象中好\n手机上操作确实别扭，瞄准全靠手指，打了两把就放弃了\n#通勤', 19, '2026-09-04 17:33:22', 302, 16, 2, 8, 0, 0, '0', '2026-09-04 18:58:22'),
(133, '这局纯靠自己，随便聊聊', '开局他就把唯一的医疗包拿走了，中途还一直喊我给他掩护\n这游戏真的需要沟通，但有些人的沟通就是指挥别人\n双排的时候他全程在聊别的，报点报错两次，我直接闭麦\n#队友', 72, '2026-09-04 22:43:09', 92, 6, 1, 0, 0, 0, '0', NULL),
(134, '操场晚上人真多，真的会谢', '晚上八点的操场全是人，跑道内圈被散步的占了，跑快一点就得一直绕\n打球的时候踩到别人脚，脚踝肿了一圈，冰敷完还是很疼，明天估计得去医院', 24, '2026-09-05 00:23:29', 103, 6, 1, 5, 2, 0, '0', NULL),
(135, '灯光调了一晚上，在线等', '这套加起来花了不到六百，键盘是二手的，鼠标垫打折买的，性价比还行\n毕业前最后一次折腾，之后这些东西要么带走要么卖，想着有点舍不得\n说真的，外设对水平提升有限，但心情提升很大\n折腾了一晚，桌面终于像样了，显示器抬高一点脖子舒服很多', 87, '2026-09-05 00:43:24', 92, 3, 1, 11, 0, 0, '0', '2026-09-05 01:46:24'),
(136, '食堂的隐藏吃法，人麻了', '三楼新开了一个窗口，卖砂锅和炒饭，今天试了砂锅饭，量足味道也还行\n食堂整体水平在涨，比以前好，就是价格也涨了\n那个新出的凉拌菜别点，醋放太多，吃两口就腻\n新窗口今天排了二十分钟，主要现做比较慢，味道对得起等待 #新菜', 87, '2026-09-05 00:46:38', 275, 3, 1, 1, 0, 0, '0', NULL),
(137, '入耳戴久了耳朵疼，有感而发', '一百多的耳机日常够用，追求音质得加预算，但学生党没必要\n宿舍里耳机是必需品，不然你会听到所有你想不到的声音\n建议先试戴，每个人耳道不一样，别人说舒服你不一定\n#耳机', 28, '2026-09-05 00:47:27', 289, 0, 2, 0, 0, 0, '0', '2026-09-05 01:51:27'),
(138, '结局有点意难平，有点破防', '断断续续玩了二十多个小时，昨晚终于通关，结局那段我看了两遍\n这游戏的解谜设计挺讲究，卡了我三次，每次想通都挺爽\n打折的时候买的，三十多块，值这个价', 87, '2026-09-05 03:12:51', 84, 1, 1, 4, 0, 0, '0', NULL),
(139, '秋招简历求看，记录一下', '建议找同学互看简历，自己看永远看不出问题\n实习经历是硬门槛，没有的话就把课设做深，至少能讲清楚\n项目只有一个课设，写出来总觉得单薄，不知道要不要包装一下 #秋招', 53, '2026-09-05 05:13:34', 67, 7, 2, 1, 0, 0, '0', '2026-09-05 05:35:34'),
(140, '打饭阿姨的手到底抖不抖，笑不活了', '今天打了三个菜一共十四块，感觉比上学期贵了两块，不知道是不是我记错\n食堂的汤永远是温的，喝完更渴', 28, '2026-09-05 06:35:38', 74, 0, 2, 1, 0, 0, '0', '2026-09-05 06:51:38'),
(141, '桌面终于收拾好了，记录一下', '折腾了一晚，桌面终于像样了，显示器抬高一点脖子舒服很多\n毕业前最后一次折腾，之后这些东西要么带走要么卖，想着有点舍不得\n新鼠标垫是大号的，键盘鼠标都能放上去，滑起来比以前顺\n#外设', 62, '2026-09-05 07:53:12', 190, 15, 2, 7, 4, 0, '0', '2026-09-05 09:18:12'),
(142, '下午四点的图书馆，记录一下', '闭馆音乐一响，整层楼同时开始收东西，那场面挺壮观\n今天硬坐了两个小时，效率还行，至少把昨天的实验报告写完了\n占座的人一半不在，桌上堆着书和水杯，人不知道去哪了', 72, '2026-09-05 18:07:02', 255, 15, 1, 4, 2, 0, '0', '2026-09-05 18:11:02'),
(143, '单机通关了，在线等', '这游戏的解谜设计挺讲究，卡了我三次，每次想通都挺爽\n打折的时候买的，三十多块，值这个价 #剧情', 69, '2026-09-05 21:44:32', 288, 0, 1, 1, 0, 0, '0', '2026-09-05 22:26:32'),
(144, '这个菜千万别点，有点破防', '那个新出的凉拌菜别点，醋放太多，吃两口就腻\n二楼的红烧肉今天炖得很烂，就是有点咸，配米饭刚好 #食堂', 19, '2026-09-05 21:56:11', 122, 1, 2, 8, 0, 0, '0', NULL),
(145, '面试被问懵了，人麻了', '二面挂在场景题上，问我并发下怎么保证幂等，我只答了一半\n八股文真的背不完，昨天背的今天忘，感觉在跟自己对抗\n建议面试前把项目里每个技术选型的原因想清楚，这个比背题重要\n面试被问到项目里为什么用 Redis，我讲了一堆缓存，他说那不加行不行，我卡住了 #面试', 61, '2026-09-05 22:44:22', 104, 1, 2, 6, 0, 0, '0', NULL),
(146, '图书馆四楼又满了，随便聊聊', '今天硬坐了两个小时，效率还行，至少把昨天的实验报告写完了\n下午两点去图书馆，四楼靠窗的位置全没了，只剩墙角一个没插座的位置\n占座的人一半不在，桌上堆着书和水杯，人不知道去哪了', 19, '2026-09-05 23:56:55', 206, 24, 2, 14, 4, 0, '0', NULL),
(147, '期末周的第一天，先记下来', '昨天通宵到三点，今天上课全程在飘，笔记写到一半变成了横线\n期末周正式开始，课表上还剩四门，我一门都没复习完 #复习', 69, '2026-09-06 15:18:44', 390, 29, 2, 3, 3, 0, '0', '2026-09-06 15:20:44'),
(148, '课设终于跑起来了，人麻了', '前后端联调跑不通，最后发现是跨域配置写漏了一行，找了两个小时\n部署到服务器之后才发现本地能跑不代表线上能跑，端口和防火墙都是坑\n建议早点开始，最后一周才开始的话基本是在赌运气', 25, '2026-09-06 18:51:42', 288, 0, 1, 4, 0, 0, '0', NULL),
(149, '今天这碗米粉，记录一下', '外地朋友第一次吃可能受不了酸笋的味道，建议先少放一点\n个人口味：卤菜粉加锅烧，酸豆角多放，辣椒少放，最后一定要加一勺卤水\n学校后门那家我吃了两年，老板记得我不要葱，加汤的时候会多给一勺', 28, '2026-09-06 19:40:45', 273, 0, 2, 3, 0, 0, '0', '2026-09-06 20:03:45'),
(150, '联调跑不通，谁懂啊', '课设终于跑起来了，五个服务加网关，启动顺序错了就各种 503，折腾了一晚上\n建议早点开始，最后一周才开始的话基本是在赌运气\n答辩 PPT 做完了，二十页，讲稿还没写，估计要练三四遍 #微服务', 19, '2026-09-07 01:22:08', 176, 0, 1, 0, 0, 0, '0', '2026-09-07 02:13:08'),
(151, '体测又要来了，真的会谢', '跑步别穿板鞋，我上周穿板鞋跑了三公里，脚底板疼了四天\n坚持晨跑第五天，今天早上有雾，跑道尽头看不太清，跑起来倒挺舒服\n晚上八点的操场全是人，跑道内圈被散步的占了，跑快一点就得一直绕 #夜跑', 18, '2026-09-07 03:09:08', 323, 27, 1, 4, 6, 0, '0', NULL),
(152, '寄快递被收了十二块，在线等', '快递柜全满，只能放驿站，结果驿站六点半就关门，我下课赶过去刚好关灯\n双十一前后建议错峰，晚上九点去人最少，就是得摸黑找箱子\n驿站阿姨已经认识我了，看到我就直接把我那个箱子拎出来，效率高得吓人 #快递', 36, '2026-09-07 18:16:51', 239, 4, 1, 0, 2, 0, '0', NULL),
(153, '我们宿舍的绿萝活下来了，说说你们那边', '室友每天凌晨两点还在打游戏，键盘声一直响，我说了三次，他答应得好好的\n隔壁宿舍搬走了，留下一股泡面味，三天没散\n宿舍四个人共用一个插排，谁先插上谁有理\n洗衣房四台机器坏了两个，剩下两个永远有人排队，我已经抱着衣服站了四十分钟', 39, '2026-09-07 22:11:04', 384, 11, 1, 18, 2, 0, '0', NULL),
(154, '今天这碗米粉，在线等', '早餐吃粉已经成习惯，一天不吃总觉得少点什么\n最近涨了一块，量倒是没变，也能接受\n外地朋友第一次吃可能受不了酸笋的味道，建议先少放一点 #桂林米粉', 18, '2026-09-07 22:47:49', 141, 0, 2, 0, 0, 0, '0', NULL),
(155, '背单词的第30天，记录一下', '四级第二次考，还是差了几分，听力部分实在跟不上\n这次考前做了五套真题，感觉比上次稳，希望能过\n四级建议先做真题，把题型摸熟，比背单词提分快', 28, '2026-09-07 22:50:00', 274, 7, 1, 10, 1, 0, '0', NULL),
(156, '项目怎么写才不虚，说说你们那边', '实习经历是硬门槛，没有的话就把课设做深，至少能讲清楚\n投了三十家，已读的不到十家，回信两家，心态有点崩', 72, '2026-09-08 03:27:50', 305, 10, 2, 4, 2, 0, '0', NULL),
(157, '教学楼后面的落日，随便聊聊', '手机拍出来比肉眼差远了，颜色压得很平，凑合看\n梧桐叶开始黄了，路灯一亮，地上全是碎影子\n沿着操场外圈走了一圈，风挺凉，穿短袖已经有点顶不住\n拍了十几张，只有这张勉强能发，其他全糊了 #晚霞', 42, '2026-09-08 05:24:56', 351, 6, 1, 19, 3, 0, '0', '2026-09-08 06:20:56'),
(158, '键盘手感差异好大，求个建议', '宿舍里建议红轴或者静音轴，青轴真的会得罪人\n从薄膜换到机械，第一天打字速度反而变慢了，一周之后才习惯', 69, '2026-09-08 08:08:20', 114, 12, 1, 0, 1, 0, '0', NULL),
(159, '宿舍网又卡了，记录一下', '建议错峰，晚上十一点之后反而稳，可能是因为大家都去睡了\n开加速器能压到六十左右，就是每个月要交钱，学生党有点心疼\n断线重连三次，第四次直接被判挂机，信誉分掉了不少 #校园网', 52, '2026-09-08 08:29:48', 141, 7, 2, 3, 1, 0, '0', '2026-09-08 09:42:48'),
(160, '匹配到的队友真行，先记下来', '建议找固定队友，随机匹配太考验心态\n我死了之后他在旁边舔包舔了半分钟，最后被人家一枪带走，我也没觉得可惜\n双排的时候他全程在聊别的，报点报错两次，我直接闭麦\n开局他就把唯一的医疗包拿走了，中途还一直喊我给他掩护', 87, '2026-09-08 17:07:24', 285, 16, 2, 3, 2, 0, '0', '2026-09-08 17:16:24'),
(161, '今天又喂了猫，真的会谢', '有同学给它搭了个纸箱窝，第二天被人扔了，气得在群里骂了半小时\n我买了一小袋猫粮，结果引来四只，最后那只橘的吃最多，还打我\n宿舍楼下那只狸花今天蹲在窗台上晒太阳，我蹲下来它就往我腿边蹭', 69, '2026-09-09 03:45:57', 143, 6, 1, 17, 2, 0, '0', NULL),
(162, '耳机求推荐，有感而发', '建议先试戴，每个人耳道不一样，别人说舒服你不一定\n一百多的耳机日常够用，追求音质得加预算，但学生党没必要 #降噪', 44, '2026-09-09 04:05:32', 160, 5, 2, 6, 0, 0, '0', NULL),
(163, '食堂上新了，说说你们那边', '新窗口今天排了二十分钟，主要现做比较慢，味道对得起等待\n隐藏吃法是打一份白饭加两块钱的蒸蛋，再要一勺免费的汤，一共不到五块', 89, '2026-09-09 05:34:16', 196, 4, 2, 3, 1, 0, '0', '2026-09-09 06:34:16'),
(164, '早八教室的第一排，笑不活了', '七点五十的校园很安静，只有保洁阿姨和几个和我一样狂奔的人\n早八最痛苦的不是上课，是要在前一晚十二点前睡着\n第一排永远没人坐，我坐了一次，被点名回答了三个问题 #校园日常', 83, '2026-09-09 18:50:48', 156, 6, 1, 2, 0, 0, '0', '2026-09-09 19:07:48'),
(165, '傍晚散步随手拍，记录一下', '手机拍出来比肉眼差远了，颜色压得很平，凑合看\n梧桐叶开始黄了，路灯一亮，地上全是碎影子\n#晚霞', 77, '2026-09-09 21:21:05', 349, 15, 1, 1, 3, 0, '0', NULL),
(166, '早八人今天的命是闹钟给的，先记下来', '今天差点迟到，进门的时候老师已经在讲第二页了，我从前门走到最后一排，全程被看着\n第一排永远没人坐，我坐了一次，被点名回答了三个问题\n秋天的早上真的起不来，被子一裹就不想动，感觉床有引力\n#校园日常', 39, '2026-09-10 01:05:31', 284, 5, 1, 0, 0, 0, '0', NULL),
(167, '青轴真的吵，记录一下', '青轴声音太大，室友已经抗议两次，我准备换静音轴\n从薄膜换到机械，第一天打字速度反而变慢了，一周之后才习惯\n#键盘', 85, '2026-09-10 02:03:03', 208, 5, 2, 14, 0, 0, '0', NULL),
(168, '坚持一个月的变化，随便聊聊', '跑完顺手吃了个夜宵，等于白跑，这个循环我已经持续两周\n跑步确实会上瘾，一天不跑就难受，但膝盖也开始提醒我别太猛\n晚上九点的操场风很凉，跑完在跑道边坐着，感觉一天的疲惫都散了\n坚持一个月，体重掉了三斤，睡眠好了很多，这个收益比想象中大 #夜跑', 87, '2026-09-10 02:57:56', 103, 0, 1, 0, 0, 0, '0', '2026-09-10 03:56:56'),
(169, '室友的作息我真的受不了，先记下来', '洗衣房四台机器坏了两个，剩下两个永远有人排队，我已经抱着衣服站了四十分钟\n晚上十一点准时断电，我的电脑刚跑到一半，直接黑屏，作业没保存\n室友每天凌晨两点还在打游戏，键盘声一直响，我说了三次，他答应得好好的\n隔壁宿舍搬走了，留下一股泡面味，三天没散 #断电', 42, '2026-09-10 03:27:27', 39, 2, 1, 9, 0, 0, '1', NULL),
(170, '今天又喂了猫，人麻了', '有同学给它搭了个纸箱窝，第二天被人扔了，气得在群里骂了半小时\n这只猫耳朵上有个缺口，估计以前打过架，现在混得挺开，谁给吃的跟谁走\n宿舍楼下那只狸花今天蹲在窗台上晒太阳，我蹲下来它就往我腿边蹭 #校园猫', 43, '2026-09-11 06:19:20', 203, 3, 2, 2, 1, 0, '0', NULL),
(171, '项目怎么写才不虚，先记下来', '简历改了八遍，删掉了所有“熟悉”“了解”，改成具体做过什么，看着踏实多了\n项目只有一个课设，写出来总觉得单薄，不知道要不要包装一下', 45, '2026-09-11 19:18:35', 98, 2, 1, 0, 0, 0, '0', NULL),
(172, '开黑遇到奇葩，有点破防', '这游戏真的需要沟通，但有些人的沟通就是指挥别人\n建议找固定队友，随机匹配太考验心态\n开局他就把唯一的医疗包拿走了，中途还一直喊我给他掩护 #队友', 61, '2026-09-13 04:33:50', 398, 12, 1, 5, 2, 0, '0', NULL),
(173, '项目部署到服务器，随便聊聊', '前后端联调跑不通，最后发现是跨域配置写漏了一行，找了两个小时\n建议早点开始，最后一周才开始的话基本是在赌运气', 81, '2026-09-13 05:24:06', 232, 3, 1, 0, 1, 0, '0', NULL),
(174, '课设终于跑起来了，随便聊聊（352）', '拆分微服务的时候最麻烦的是用户信息，内容服务要调用户服务，还要处理降级\n部署到服务器之后才发现本地能跑不代表线上能跑，端口和防火墙都是坑\n前后端联调跑不通，最后发现是跨域配置写漏了一行，找了两个小时\n答辩 PPT 做完了，二十页，讲稿还没写，估计要练三四遍\n#微服务', 25, '2026-09-13 07:21:25', 192, 2, 1, 7, 1, 0, '0', NULL),
(175, '操场边上的天空，求个建议（247）', '拍了十几张，只有这张勉强能发，其他全糊了\n傍晚六点多从教学楼出来，整片天是橙红过渡到紫，我站着看了五分钟才想起拍照', 52, '2026-09-13 16:09:28', 60, 4, 2, 6, 1, 0, '1', NULL),
(176, '我们宿舍的绿萝活下来了，真的会谢', '昨晚下大雨，从窗户往外看，路灯把雨照得像在下雪，还挺好看\n室友每天凌晨两点还在打游戏，键盘声一直响，我说了三次，他答应得好好的\n洗衣房四台机器坏了两个，剩下两个永远有人排队，我已经抱着衣服站了四十分钟\n晚上十一点准时断电，我的电脑刚跑到一半，直接黑屏，作业没保存', 89, '2026-09-13 17:35:33', 326, 4, 1, 0, 1, 1, '0', NULL),
(177, '宿舍楼下的雨，先记下来', '室友每天凌晨两点还在打游戏，键盘声一直响，我说了三次，他答应得好好的\n隔壁宿舍搬走了，留下一股泡面味，三天没散\n洗衣房四台机器坏了两个，剩下两个永远有人排队，我已经抱着衣服站了四十分钟', 77, '2026-09-13 21:01:27', 164, 1, 2, 2, 0, 0, '0', '2026-09-13 21:58:27'),
(178, '食堂是不是涨价了，说说你们那边', '二楼最右边那个窗口的粉蒸肉是真的香，就是每次只剩一点点\n中午十二点十分到食堂，队伍已经排到楼梯拐角，前面大概四十个人\n阿姨给我的肉明显比别人少，我怀疑是看我不顺眼，但我没说\n食堂的汤永远是温的，喝完更渴 #食堂', 72, '2026-09-13 21:26:34', 356, 35, 1, 0, 5, 0, '0', NULL),
(179, '复习不完了，笑不活了', '昨天通宵到三点，今天上课全程在飘，笔记写到一半变成了横线\n期末周正式开始，课表上还剩四门，我一门都没复习完\n复习效率最高的时候是考前两小时，其余时间都在整理桌面\n#期末周', 19, '2026-09-14 01:15:10', 82, 3, 1, 5, 0, 0, '0', NULL),
(180, '二手笔记本靠谱吗，有点破防', '别信“全新未拆”的低价，八成是翻新，这个坑我踩过\n看了几款，同价位游戏本显卡好但重，轻薄本续航好但散热差，很难两全\n最后买了轻薄本，重量一点三公斤，通勤背着不累，就是风扇一开声音大\n#笔记本', 24, '2026-09-14 17:41:33', 47, 4, 1, 2, 0, 0, '0', NULL),
(181, '实习工资够花吗，谁懂啊', '每天通勤来回两小时，早上六点半出门，晚上八点到宿舍，人确实有点疲\n纠结要不要继续，学校那边还有课，两边都顾着有点吃不消\n实习工资一天一百二，扣掉吃饭和通勤，基本不剩，主要是攒经验\n带我的师傅挺耐心，我提的问题再基础他也会讲，这点挺感激', 54, '2026-09-14 20:05:59', 137, 2, 2, 3, 1, 0, '0', NULL),
(182, '宿舍楼下的雨，笑不活了', '宿舍四个人共用一个插排，谁先插上谁有理\n昨晚下大雨，从窗户往外看，路灯把雨照得像在下雪，还挺好看\n#断电', 69, '2026-09-15 03:42:41', 223, 10, 1, 2, 2, 0, '0', '2026-09-15 03:45:41'),
(183, '宿舍今晚又断电了，真的会谢', '昨晚下大雨，从窗户往外看，路灯把雨照得像在下雪，还挺好看\n宿舍四个人共用一个插排，谁先插上谁有理', 54, '2026-09-15 04:47:22', 670, 48, 1, 7, 6, 0, '0', NULL),
(184, '七点五十的校园，人麻了', '秋天的早上真的起不来，被子一裹就不想动，感觉床有引力\n早八最痛苦的不是上课，是要在前一晚十二点前睡着\n闹钟从六点四十响到七点十分，我才爬起来，刷牙的时候还在想要不要装病\n今天差点迟到，进门的时候老师已经在讲第二页了，我从前门走到最后一排，全程被看着\n#早八人', 61, '2026-09-15 04:59:19', 198, 1, 1, 1, 1, 0, '0', '2026-09-15 05:01:19'),
(185, '通宵自习警告，在线等', '建议别通宵，第二天脑子是空的，我试过，代价很大\n复习效率最高的时候是考前两小时，其余时间都在整理桌面', 52, '2026-09-15 14:03:18', 136, 2, 1, 3, 0, 0, '0', '2026-09-15 15:33:18'),
(186, '一百多的耳机够用吗，求个建议', '一百多的耳机日常够用，追求音质得加预算，但学生党没必要\n建议先试戴，每个人耳道不一样，别人说舒服你不一定\n预算两百以内，主要通勤和自习用，纠结入耳还是头戴 #耳机', 19, '2026-09-15 17:11:50', 228, 5, 1, 4, 2, 0, '0', NULL),
(187, '单人打了一把，有点破防', '新手别急着冲，先把地图记熟，不然你会像我一样在出生点转圈\n今晚打了六把，赢了四把，手感比上周好太多，主要是换了灵敏度\n这游戏最上头的不是赢，是差一点就赢\n刚刚那把在最后三十秒被人从背后偷了，我全程没听到脚步，回放看了三遍 #排位', 52, '2026-09-16 00:34:08', 365, 15, 2, 6, 3, 1, '0', '2026-09-16 01:19:08'),
(188, '这局纯靠自己，谁懂啊', '我死了之后他在旁边舔包舔了半分钟，最后被人家一枪带走，我也没觉得可惜\n双排的时候他全程在聊别的，报点报错两次，我直接闭麦\n最后我一个人守住了，队友在语音里一句“哥牛”，我气就消了一半\n这游戏真的需要沟通，但有些人的沟通就是指挥别人', 87, '2026-09-16 00:43:00', 283, 5, 1, 2, 0, 0, '0', NULL),
(189, '考研人的一天，谁懂啊', '建议每天留一小时运动，不然到后期身体先垮\n每天六点半起，晚上十一点回，中间有效学习时间大概七个小时，剩下都在走神\n倒计时五十天，专业课还有两章没背，英语真题做到第三遍还是在错同一类题\n#考研', 59, '2026-09-16 22:52:05', 201, 1, 1, 12, 0, 0, '0', '2026-09-16 23:01:05'),
(190, '一面过了，求个建议', '面试官挺耐心，我答错的地方他会引导，聊完反而学到东西\n面试被问到项目里为什么用 Redis，我讲了一堆缓存，他说那不加行不行，我卡住了\n#秋招', 25, '2026-09-16 23:28:38', 302, 7, 1, 9, 2, 0, '0', NULL),
(191, '今天的晚霞，求个建议', '手机拍出来比肉眼差远了，颜色压得很平，凑合看\n梧桐叶开始黄了，路灯一亮，地上全是碎影子\n拍了十几张，只有这张勉强能发，其他全糊了\n沿着操场外圈走了一圈，风挺凉，穿短袖已经有点顶不住 #随手拍', 28, '2026-09-17 07:39:36', 115, 1, 2, 3, 0, 0, '0', NULL),
(192, '我们宿舍的绿萝活下来了，谁懂啊', '宿舍四个人共用一个插排，谁先插上谁有理\n昨晚下大雨，从窗户往外看，路灯把雨照得像在下雪，还挺好看\n洗衣房四台机器坏了两个，剩下两个永远有人排队，我已经抱着衣服站了四十分钟\n室友每天凌晨两点还在打游戏，键盘声一直响，我说了三次，他答应得好好的', 57, '2026-09-17 08:16:44', 326, 3, 1, 0, 1, 0, '0', NULL),
(193, '这次应该能过，随便聊聊', '英语这东西停一个月就废，别指望突击\n四级第二次考，还是差了几分，听力部分实在跟不上\n四级建议先做真题，把题型摸熟，比背单词提分快 #四六级', 69, '2026-09-17 18:00:08', 231, 4, 2, 2, 2, 0, '0', NULL),
(194, '遇到这种队友怎么办，有感而发', '建议找固定队友，随机匹配太考验心态\n开局他就把唯一的医疗包拿走了，中途还一直喊我给他掩护\n双排的时候他全程在聊别的，报点报错两次，我直接闭麦\n最后我一个人守住了，队友在语音里一句“哥牛”，我气就消了一半', 52, '2026-09-18 03:54:56', 284, 3, 1, 0, 0, 0, '0', NULL),
(195, '宿舍楼下那只狸花，先记下来', '有同学给它搭了个纸箱窝，第二天被人扔了，气得在群里骂了半小时\n我买了一小袋猫粮，结果引来四只，最后那只橘的吃最多，还打我\n宿舍楼下那只狸花今天蹲在窗台上晒太阳，我蹲下来它就往我腿边蹭\n#撸猫', 87, '2026-09-18 04:14:42', 104, 1, 2, 1, 1, 0, '0', NULL),
(196, '体测又要来了，谁懂啊', '晚上八点的操场全是人，跑道内圈被散步的占了，跑快一点就得一直绕\n操场边上的自动售货机永远缺货，只有无糖茶，喝起来像草\n打球的时候踩到别人脚，脚踝肿了一圈，冰敷完还是很疼，明天估计得去医院\n跑步别穿板鞋，我上周穿板鞋跑了三公里，脚底板疼了四天\n#夜跑', 55, '2026-09-18 06:31:10', 367, 6, 2, 20, 1, 0, '0', NULL),
(197, '宿舍今晚又断电了，有点破防', '宿舍四个人共用一个插排，谁先插上谁有理\n昨晚下大雨，从窗户往外看，路灯把雨照得像在下雪，还挺好看\n晚上十一点准时断电，我的电脑刚跑到一半，直接黑屏，作业没保存\n洗衣房四台机器坏了两个，剩下两个永远有人排队，我已经抱着衣服站了四十分钟 #断电', 77, '2026-09-18 13:28:32', 294, 7, 2, 0, 2, 0, '0', NULL),
(198, '米粉又涨价了，随便聊聊', '最近涨了一块，量倒是没变，也能接受\n外地朋友第一次吃可能受不了酸笋的味道，建议先少放一点\n个人口味：卤菜粉加锅烧，酸豆角多放，辣椒少放，最后一定要加一勺卤水\n学校后门那家我吃了两年，老板记得我不要葱，加汤的时候会多给一勺', 83, '2026-09-18 15:48:43', 150, 3, 2, 2, 1, 0, '0', NULL),
(199, '宿舍楼下那只狸花，笑不活了', '宿舍楼下那只狸花今天蹲在窗台上晒太阳，我蹲下来它就往我腿边蹭\n有同学给它搭了个纸箱窝，第二天被人扔了，气得在群里骂了半小时\n提醒一下，别喂太咸的东西，上次有人喂火腿肠，猫拉了两天肚子 #校园猫', 72, '2026-09-18 21:07:21', 212, 13, 1, 6, 3, 0, '0', '2026-09-18 22:31:21'),
(200, '灯光调了一晚上，记录一下', '灯带贴在显示器后面，晚上关灯的时候氛围感确实有，就是有点晃眼\n这套加起来花了不到六百，键盘是二手的，鼠标垫打折买的，性价比还行\n毕业前最后一次折腾，之后这些东西要么带走要么卖，想着有点舍不得', 43, '2026-09-18 22:41:00', 338, 8, 1, 7, 6, 0, '0', '2026-09-18 22:56:00');
INSERT INTO `news` (`id`, `title`, `content`, `user_id`, `create_time`, `view_count`, `like_count`, `media_type`, `comment_count`, `collect_count`, `status`, `is_deleted`, `update_time`) VALUES
(201, '七点五十的校园，有感而发', '第一排永远没人坐，我坐了一次，被点名回答了三个问题\n秋天的早上真的起不来，被子一裹就不想动，感觉床有引力\n七点五十的校园很安静，只有保洁阿姨和几个和我一样狂奔的人', 87, '2026-09-19 05:33:28', 182, 7, 2, 6, 1, 1, '0', '2026-09-19 06:02:28'),
(202, '快递站又排长队，真的会谢', '下课去快递站，前面排了三十多个人，队伍拐了两个弯\n双十一前后建议错峰，晚上九点去人最少，就是得摸黑找箱子 #快递', 87, '2026-09-19 07:08:22', 226, 6, 1, 1, 2, 0, '0', NULL),
(203, '食堂的隐藏吃法，先记下来', '三楼新开了一个窗口，卖砂锅和炒饭，今天试了砂锅饭，量足味道也还行\n那个新出的凉拌菜别点，醋放太多，吃两口就腻\n#食堂', 80, '2026-09-19 22:39:46', 28, 0, 1, 0, 0, 0, '0', NULL),
(204, '今晚手感不错，在线等', '这游戏最上头的不是赢，是差一点就赢\n排位连跪五把，队友全程各玩各的，我索性关麦自己打\n新手别急着冲，先把地图记熟，不然你会像我一样在出生点转圈 #三角洲行动', 77, '2026-09-20 05:45:11', 289, 5, 1, 0, 0, 0, '0', '2026-09-20 05:53:11'),
(205, '四楼靠窗位又被占了，笑不活了', '提醒一下，现在晚上十点半清场，别睡过头被保安叫醒\n闭馆音乐一响，整层楼同时开始收东西，那场面挺壮观\n下午两点去图书馆，四楼靠窗的位置全没了，只剩墙角一个没插座的位置 #图书馆', 69, '2026-09-20 07:15:09', 177, 1, 1, 4, 0, 0, '0', NULL),
(206, '今天这个菜不错，随便聊聊', '那个新出的凉拌菜别点，醋放太多，吃两口就腻\n二楼的红烧肉今天炖得很烂，就是有点咸，配米饭刚好\n食堂整体水平在涨，比以前好，就是价格也涨了\n#新菜', 24, '2026-09-20 08:50:27', 327, 11, 1, 14, 2, 0, '0', NULL),
(207, '课设终于跑起来了，随便聊聊', '拆分微服务的时候最麻烦的是用户信息，内容服务要调用户服务，还要处理降级\n答辩 PPT 做完了，二十页，讲稿还没写，估计要练三四遍\n课设终于跑起来了，五个服务加网关，启动顺序错了就各种 503，折腾了一晚上\n建议早点开始，最后一周才开始的话基本是在赌运气', 20, '2026-09-20 15:54:09', 254, 1, 1, 0, 0, 0, '0', NULL),
(208, '下午四点的图书馆，说说你们那边', '下午两点去图书馆，四楼靠窗的位置全没了，只剩墙角一个没插座的位置\n占座的人一半不在，桌上堆着书和水杯，人不知道去哪了\n闭馆音乐一响，整层楼同时开始收东西，那场面挺壮观', 43, '2026-09-20 22:15:45', 294, 0, 1, 0, 0, 0, '0', '2026-09-20 22:53:45'),
(209, '键盘手感差异好大，先记下来', '从薄膜换到机械，第一天打字速度反而变慢了，一周之后才习惯\n键盘这种外设，适合自己的就是最好的，别人推荐只能参考\n宿舍里建议红轴或者静音轴，青轴真的会得罪人', 71, '2026-09-20 22:57:18', 335, 11, 1, 4, 1, 0, '0', NULL),
(210, '打游戏必须开加速器，真的会谢', '开加速器能压到六十左右，就是每个月要交钱，学生党有点心疼\n打这种需要反应的游戏，延迟比配置重要，我算是体会到了 #延迟', 22, '2026-09-21 00:50:01', 340, 4, 2, 4, 2, 0, '0', NULL),
(211, '换了新鼠标垫，先记下来', '这套加起来花了不到六百，键盘是二手的，鼠标垫打折买的，性价比还行\n灯带贴在显示器后面，晚上关灯的时候氛围感确实有，就是有点晃眼\n新鼠标垫是大号的，键盘鼠标都能放上去，滑起来比以前顺\n折腾了一晚，桌面终于像样了，显示器抬高一点脖子舒服很多', 69, '2026-09-21 00:54:54', 209, 6, 2, 0, 1, 0, '0', NULL),
(212, '这个菜千万别点，谁懂啊', '那个新出的凉拌菜别点，醋放太多，吃两口就腻\n二楼的红烧肉今天炖得很烂，就是有点咸，配米饭刚好', 43, '2026-09-21 06:35:26', 244, 2, 1, 4, 1, 0, '0', NULL),
(213, '楼下便利店换老板了，有感而发', '凌晨一点去楼下便利店，只有关东煮和泡面，收银小哥在打瞌睡\n换老板之后关东煮味道变了，汤淡了不少，我去得少了', 82, '2026-09-21 07:01:33', 300, 7, 1, 2, 3, 0, '0', '2026-09-21 07:51:33'),
(214, '结局有点意难平，笑不活了', '重玩一遍才发现前面埋了很多伏笔，第一遍完全没注意\n这游戏的解谜设计挺讲究，卡了我三次，每次想通都挺爽\n单机的好处是不用等队友，坏处是通关之后有点空\n断断续续玩了二十多个小时，昨晚终于通关，结局那段我看了两遍', 56, '2026-09-21 16:07:46', 212, 12, 1, 1, 2, 0, '0', '2026-09-21 17:36:46'),
(215, '简历被已读了，笑不活了', '项目只有一个课设，写出来总觉得单薄，不知道要不要包装一下\n简历改了八遍，删掉了所有“熟悉”“了解”，改成具体做过什么，看着踏实多了\n建议找同学互看简历，自己看永远看不出问题\n实习经历是硬门槛，没有的话就把课设做深，至少能讲清楚', 19, '2026-09-21 19:30:40', 197, 1, 2, 0, 0, 1, '0', '2026-09-21 19:32:40'),
(216, '秋天的早上真起不来，谁懂啊', '早八最痛苦的不是上课，是要在前一晚十二点前睡着\n秋天的早上真的起不来，被子一裹就不想动，感觉床有引力', 72, '2026-09-21 20:19:08', 58, 3, 1, 3, 0, 0, '0', '2026-09-21 20:27:08'),
(217, '自习到闭馆，人麻了', '今天硬坐了两个小时，效率还行，至少把昨天的实验报告写完了\n提醒一下，现在晚上十点半清场，别睡过头被保安叫醒\n占座的人一半不在，桌上堆着书和水杯，人不知道去哪了 #图书馆', 49, '2026-09-21 22:02:42', 289, 4, 2, 44, 0, 1, '0', '2026-09-21 22:21:42'),
(218, '选笔记本求建议，谁懂啊', '看了几款，同价位游戏本显卡好但重，轻薄本续航好但散热差，很难两全\n别信“全新未拆”的低价，八成是翻新，这个坑我踩过\n写代码其实不需要太高的配置，内存加到十六G比什么都管用\n#笔记本', 33, '2026-09-21 23:21:44', 202, 12, 1, 1, 2, 0, '0', NULL),
(219, '体测又要来了，笑不活了', '打球的时候踩到别人脚，脚踝肿了一圈，冰敷完还是很疼，明天估计得去医院\n操场边上的自动售货机永远缺货，只有无糖茶，喝起来像草', 52, '2026-09-22 03:50:00', 539, 34, 1, 2, 7, 0, '0', '2026-09-22 04:18:00'),
(220, '跑道上的雾，谁懂啊', '打球的时候踩到别人脚，脚踝肿了一圈，冰敷完还是很疼，明天估计得去医院\n操场边上的自动售货机永远缺货，只有无糖茶，喝起来像草\n坚持晨跑第五天，今天早上有雾，跑道尽头看不太清，跑起来倒挺舒服\n跑步别穿板鞋，我上周穿板鞋跑了三公里，脚底板疼了四天', 75, '2026-09-22 04:40:01', 152, 2, 2, 2, 0, 0, '0', NULL),
(221, '宿舍今晚又断电了，求个建议', '隔壁宿舍搬走了，留下一股泡面味，三天没散\n洗衣房四台机器坏了两个，剩下两个永远有人排队，我已经抱着衣服站了四十分钟\n昨晚下大雨，从窗户往外看，路灯把雨照得像在下雪，还挺好看 #断电', 46, '2026-09-22 06:14:20', 261, 1, 1, 8, 0, 0, '0', '2026-09-22 06:28:20'),
(222, '今天这杯奶茶，先记下来', '奶茶这东西，喝的时候快乐，喝完有点后悔，第二天还是想喝\n无糖选项其实是少糖，喝起来还是有甜味，不过热量确实低一些\n校门口那家新店，第二杯半价，排了半个小时，喝完觉得不太值\n这周已经喝了四杯，钱包和体重都在抗议 #续命', 93, '2026-09-22 08:16:10', 232, 2, 1, 3, 0, 0, '0', NULL),
(223, '通宵自习警告，求个建议（365）', '第一门考完感觉还行，选择题全靠直觉，问答题把能想到的都写了\n复习效率最高的时候是考前两小时，其余时间都在整理桌面\n昨天通宵到三点，今天上课全程在飘，笔记写到一半变成了横线 #复习', 86, '2026-09-22 23:28:27', 213, 0, 2, 5, 0, 0, '0', '2026-09-22 23:51:27'),
(224, '早餐吃粉的第N天，记录一下', '最近涨了一块，量倒是没变，也能接受\n今天这碗加了锅烧和卤蛋，一共十一块，汤头够味，酸笋放得刚好', 72, '2026-09-23 01:03:47', 220, 0, 1, 18, 0, 0, '0', NULL),
(225, '傍晚散步随手拍，有点破防', '梧桐叶开始黄了，路灯一亮，地上全是碎影子\n这个点最适合发呆，什么都不想干，也不想回宿舍\n手机拍出来比肉眼差远了，颜色压得很平，凑合看', 34, '2026-09-23 14:09:30', 257, 5, 1, 0, 0, 0, '0', NULL),
(226, '十二点的食堂，有点破防', '食堂的汤永远是温的，喝完更渴\n中午十二点十分到食堂，队伍已经排到楼梯拐角，前面大概四十个人\n阿姨给我的肉明显比别人少，我怀疑是看我不顺眼，但我没说\n#干饭', 75, '2026-09-23 17:51:22', 199, 16, 1, 25, 4, 0, '0', '2026-09-23 18:20:22'),
(227, '凌晨的便利店，谁懂啊', '凌晨一点去楼下便利店，只有关东煮和泡面，收银小哥在打瞌睡\n半夜饿了不想出门，翻遍宿舍只有一包泡面和一袋饼干\n换老板之后关东煮味道变了，汤淡了不少，我去得少了', 73, '2026-09-24 07:19:09', 86, 7, 1, 0, 1, 0, '0', NULL),
(228, '取个快递像赶集，真的会谢', '下课去快递站，前面排了三十多个人，队伍拐了两个弯\n驿站阿姨已经认识我了，看到我就直接把我那个箱子拎出来，效率高得吓人\n快递柜全满，只能放驿站，结果驿站六点半就关门，我下课赶过去刚好关灯', 82, '2026-09-24 14:54:59', 79, 1, 2, 6, 0, 0, '0', '2026-09-24 16:10:59'),
(229, '遇到这种队友怎么办，真的会谢', '双排的时候他全程在聊别的，报点报错两次，我直接闭麦\n建议找固定队友，随机匹配太考验心态\n#开黑', 64, '2026-09-24 18:18:26', 274, 4, 1, 10, 2, 0, '0', NULL),
(230, '这种天色只有秋天有，在线等', '这个点最适合发呆，什么都不想干，也不想回宿舍\n拍了十几张，只有这张勉强能发，其他全糊了\n梧桐叶开始黄了，路灯一亮，地上全是碎影子', 43, '2026-09-25 00:34:10', 261, 6, 2, 0, 6, 0, '0', '2026-09-25 01:06:10'),
(231, '面试官人挺好，说说你们那边', '一面感觉一般，手撕代码写出来了但边界没处理好，居然过了\n二面挂在场景题上，问我并发下怎么保证幂等，我只答了一半\n面试官挺耐心，我答错的地方他会引导，聊完反而学到东西\n八股文真的背不完，昨天背的今天忘，感觉在跟自己对抗', 81, '2026-09-25 04:28:41', 342, 4, 1, 0, 0, 0, '0', NULL),
(232, '七点五十的校园，说说你们那边', '闹钟从六点四十响到七点十分，我才爬起来，刷牙的时候还在想要不要装病\n早八最痛苦的不是上课，是要在前一晚十二点前睡着\n第一排永远没人坐，我坐了一次，被点名回答了三个问题', 69, '2026-09-25 07:11:42', 137, 3, 2, 4, 2, 0, '0', NULL),
(233, '半夜饿了，说说你们那边', '便利店是深夜唯一还亮着的地方，站在门口会有种奇怪的安全感\n同样的水便利店比超市贵一块五，但胜在近，半夜也只能认了\n换老板之后关东煮味道变了，汤淡了不少，我去得少了 #便利店', 70, '2026-09-25 08:23:15', 206, 6, 2, 4, 0, 0, '0', '2026-09-25 08:50:15'),
(234, '二面挂了，说说你们那边', '八股文真的背不完，昨天背的今天忘，感觉在跟自己对抗\n面试被问到项目里为什么用 Redis，我讲了一堆缓存，他说那不加行不行，我卡住了\n面试官挺耐心，我答错的地方他会引导，聊完反而学到东西\n建议面试前把项目里每个技术选型的原因想清楚，这个比背题重要\n#秋招', 75, '2026-09-25 17:43:45', 134, 1, 1, 0, 0, 0, '0', '2026-09-25 18:37:45'),
(235, '队友把我卖了，人麻了', '这游戏真的需要沟通，但有些人的沟通就是指挥别人\n我死了之后他在旁边舔包舔了半分钟，最后被人家一枪带走，我也没觉得可惜', 77, '2026-09-25 20:48:48', 242, 1, 2, 4, 0, 0, '0', '2026-09-25 22:17:48'),
(236, '食堂排队排到楼梯口，先记下来', '阿姨给我的肉明显比别人少，我怀疑是看我不顺眼，但我没说\n今天打了三个菜一共十四块，感觉比上学期贵了两块，不知道是不是我记错', 45, '2026-09-26 00:01:53', 147, 8, 1, 0, 2, 0, '0', NULL),
(237, '操场边上的天空，人麻了', '梧桐叶开始黄了，路灯一亮，地上全是碎影子\n手机拍出来比肉眼差远了，颜色压得很平，凑合看', 77, '2026-09-26 00:46:18', 213, 1, 1, 46, 0, 0, '0', NULL),
(238, '通宵自习警告，真的会谢', '期末周正式开始，课表上还剩四门，我一门都没复习完\n第一门考完感觉还行，选择题全靠直觉，问答题把能想到的都写了\n昨天通宵到三点，今天上课全程在飘，笔记写到一半变成了横线', 83, '2026-09-26 21:20:27', 299, 4, 2, 0, 2, 0, '0', NULL),
(239, '四楼靠窗位又被占了，人麻了', '提醒一下，现在晚上十点半清场，别睡过头被保安叫醒\n占座的人一半不在，桌上堆着书和水杯，人不知道去哪了 #图书馆', 53, '2026-09-26 22:20:51', 152, 0, 1, 46, 0, 0, '0', '2026-09-26 23:39:51'),
(240, '键帽换了之后，在线等', '同样的轴体，不同键帽高度手感差别挺明显，这个之前完全没想过\n从薄膜换到机械，第一天打字速度反而变慢了，一周之后才习惯\n#外设', 86, '2026-09-26 23:24:42', 283, 2, 2, 0, 0, 0, '0', NULL),
(241, '期末周的第一天，记录一下', '昨天通宵到三点，今天上课全程在飘，笔记写到一半变成了横线\n期末周正式开始，课表上还剩四门，我一门都没复习完\n建议别通宵，第二天脑子是空的，我试过，代价很大\n复习效率最高的时候是考前两小时，其余时间都在整理桌面', 52, '2026-09-27 00:53:24', 124, 4, 1, 0, 0, 0, '0', NULL),
(242, '自习到闭馆，求个建议', '闭馆音乐一响，整层楼同时开始收东西，那场面挺壮观\n我一般坐三楼，人少，缺点是空调太冷，得带件外套\n占座的人一半不在，桌上堆着书和水杯，人不知道去哪了\n今天硬坐了两个小时，效率还行，至少把昨天的实验报告写完了 #自习', 23, '2026-09-27 02:28:08', 335, 12, 1, 0, 2, 0, '0', NULL),
(243, '早八教室的第一排，真的会谢', '第一排永远没人坐，我坐了一次，被点名回答了三个问题\n七点五十的校园很安静，只有保洁阿姨和几个和我一样狂奔的人', 23, '2026-09-27 05:30:12', 362, 21, 1, 0, 5, 0, '0', NULL),
(244, '课设终于跑起来了，记录一下', '前后端联调跑不通，最后发现是跨域配置写漏了一行，找了两个小时\n答辩 PPT 做完了，二十页，讲稿还没写，估计要练三四遍\n课设终于跑起来了，五个服务加网关，启动顺序错了就各种 503，折腾了一晚上', 82, '2026-09-27 06:15:28', 244, 2, 1, 0, 0, 0, '0', '2026-09-27 07:08:28'),
(245, '通宵自习警告，随便聊聊', '昨天通宵到三点，今天上课全程在飘，笔记写到一半变成了横线\n老师说的重点和大家整理的重点完全不是一个东西，现在有五个版本在群里流传', 75, '2026-09-27 15:46:29', 28, 0, 1, 0, 0, 0, '0', NULL),
(246, '单人打了一把，随便聊聊', '新手别急着冲，先把地图记熟，不然你会像我一样在出生点转圈\n这游戏最上头的不是赢，是差一点就赢', 83, '2026-09-27 20:42:03', 223, 8, 2, 6, 1, 0, '0', NULL),
(247, '队友把我卖了，有感而发', '我死了之后他在旁边舔包舔了半分钟，最后被人家一枪带走，我也没觉得可惜\n建议找固定队友，随机匹配太考验心态\n最后我一个人守住了，队友在语音里一句“哥牛”，我气就消了一半\n开局他就把唯一的医疗包拿走了，中途还一直喊我给他掩护\n#队友', 42, '2026-09-27 21:40:10', 89, 1, 2, 4, 0, 0, '0', NULL),
(248, '简历被已读了，说说你们那边', '简历改了八遍，删掉了所有“熟悉”“了解”，改成具体做过什么，看着踏实多了\n实习经历是硬门槛，没有的话就把课设做深，至少能讲清楚\n#秋招', 42, '2026-09-27 23:06:32', 163, 1, 2, 1, 0, 0, '0', NULL),
(249, '傍晚散步随手拍，求个建议', '拍了十几张，只有这张勉强能发，其他全糊了\n傍晚六点多从教学楼出来，整片天是橙红过渡到紫，我站着看了五分钟才想起拍照\n梧桐叶开始黄了，路灯一亮，地上全是碎影子\n#晚霞', 69, '2026-09-27 23:20:01', 159, 5, 2, 0, 2, 0, '0', '2026-09-27 23:36:01'),
(250, '实习工资够花吗，先记下来', '实习第三周，主要在做接口联调和改 bug，代码量不大，但学到了不少规范\n每天通勤来回两小时，早上六点半出门，晚上八点到宿舍，人确实有点疲', 67, '2026-09-27 23:22:00', 235, 2, 2, 7, 0, 0, '0', NULL),
(251, '教学楼后面的落日，先记下来', '手机拍出来比肉眼差远了，颜色压得很平，凑合看\n拍了十几张，只有这张勉强能发，其他全糊了\n这个点最适合发呆，什么都不想干，也不想回宿舍', 77, '2026-09-28 04:27:11', 208, 1, 1, 0, 0, 0, '0', '2026-09-28 04:43:11'),
(252, '又迟到了，人麻了', '第一排永远没人坐，我坐了一次，被点名回答了三个问题\n闹钟从六点四十响到七点十分，我才爬起来，刷牙的时候还在想要不要装病\n七点五十的校园很安静，只有保洁阿姨和几个和我一样狂奔的人', 79, '2026-09-28 13:04:23', 166, 5, 1, 3, 1, 0, '1', '2026-09-28 14:03:23'),
(253, '键盘手感差异好大，谁懂啊', '青轴声音太大，室友已经抗议两次，我准备换静音轴\n宿舍里建议红轴或者静音轴，青轴真的会得罪人\n同样的轴体，不同键帽高度手感差别挺明显，这个之前完全没想过\n从薄膜换到机械，第一天打字速度反而变慢了，一周之后才习惯', 19, '2026-09-28 18:25:32', 255, 5, 1, 3, 0, 0, '0', '2026-09-28 19:09:32'),
(254, '桌面终于收拾好了，有感而发', '说真的，外设对水平提升有限，但心情提升很大\n灯带贴在显示器后面，晚上关灯的时候氛围感确实有，就是有点晃眼\n毕业前最后一次折腾，之后这些东西要么带走要么卖，想着有点舍不得', 77, '2026-09-28 18:52:45', 240, 0, 1, 2, 0, 0, '0', '2026-09-28 19:43:45'),
(255, '手机拍照对比，真的会谢', '拍照比想象中好，白天没问题，晚上还是有点糊，日常够用\n用三年的旧手机终于换了，主要是电池不行，一天要充两次\n旧手机留着当备用机，装个卡当热点，也算物尽其用\n买之前先去实体店摸一下，手感和重量网上看不出来\n#手机', 72, '2026-09-28 23:18:08', 317, 15, 1, 1, 0, 0, '0', NULL),
(256, '青轴真的吵，说说你们那边', '换了套键帽，手感没变多少，但看着舒服，这钱花得有点虚\n键盘这种外设，适合自己的就是最好的，别人推荐只能参考\n青轴声音太大，室友已经抗议两次，我准备换静音轴\n#键盘', 34, '2026-09-29 04:48:19', 171, 1, 1, 0, 0, 0, '0', NULL),
(257, '考研人的一天，有感而发', '自习室里大家都很安静，偶尔有人叹气，那种氛围挺压抑也挺鼓励\n建议每天留一小时运动，不然到后期身体先垮', 65, '2026-09-29 16:52:55', 116, 4, 1, 0, 0, 0, '0', NULL),
(258, '笔记本风扇太吵，笑不活了', '保修期内建议别自己拆，我就是拆完发现不保修了\n风扇声音大得像起飞，拆开一看全是灰，清了之后安静不少', 69, '2026-09-30 03:19:58', 265, 4, 2, 0, 2, 1, '0', NULL),
(259, '早八教室的第一排，有感而发', '早八最痛苦的不是上课，是要在前一晚十二点前睡着\n七点五十的校园很安静，只有保洁阿姨和几个和我一样狂奔的人\n今天差点迟到，进门的时候老师已经在讲第二页了，我从前门走到最后一排，全程被看着', 43, '2026-09-30 07:54:47', 165, 6, 2, 1, 2, 0, '0', NULL),
(260, '半夜饿了，先记下来', '同样的水便利店比超市贵一块五，但胜在近，半夜也只能认了\n凌晨一点去楼下便利店，只有关东煮和泡面，收银小哥在打瞌睡\n关东煮的萝卜煮得很透，汤也好喝，就是有点贵，一串三块 #便利店', 65, '2026-09-30 09:18:08', 165, 0, 2, 14, 0, 0, '0', NULL),
(261, '宿舍楼下那只狸花，有点破防', '宿舍楼下那只狸花今天蹲在窗台上晒太阳，我蹲下来它就往我腿边蹭\n有同学给它搭了个纸箱窝，第二天被人扔了，气得在群里骂了半小时\n#撸猫', 42, '2026-09-30 10:56:31', 96, 3, 2, 0, 1, 0, '0', NULL),
(262, '旧手机还能再战，笑不活了', '拍照比想象中好，白天没问题，晚上还是有点糊，日常够用\n建议别在首发的时候买，等两个月价格能下来不少\n#数码', 72, '2026-09-30 12:02:51', 89, 5, 1, 0, 1, 0, '0', NULL),
(263, '食堂上新了，有感而发', '隐藏吃法是打一份白饭加两块钱的蒸蛋，再要一勺免费的汤，一共不到五块\n那个新出的凉拌菜别点，醋放太多，吃两口就腻\n三楼新开了一个窗口，卖砂锅和炒饭，今天试了砂锅饭，量足味道也还行\n食堂整体水平在涨，比以前好，就是价格也涨了', 77, '2026-09-30 19:47:23', 201, 1, 1, 0, 0, 0, '0', '2026-09-30 20:50:23'),
(264, '降噪真的有用，谁懂啊', '建议先试戴，每个人耳道不一样，别人说舒服你不一定\n预算两百以内，主要通勤和自习用，纠结入耳还是头戴\n宿舍里耳机是必需品，不然你会听到所有你想不到的声音', 45, '2026-10-01 02:30:03', 467, 64, 2, 5, 12, 0, '0', '2026-10-01 03:10:03'),
(265, '终于摸到金了，有感而发', '这游戏最上头的不是赢，是差一点就赢\n排位连跪五把，队友全程各玩各的，我索性关麦自己打', 69, '2026-10-01 22:01:24', 287, 4, 1, 0, 0, 0, '0', NULL),
(266, '寄快递被收了十二块，笑不活了', '下课去快递站，前面排了三十多个人，队伍拐了两个弯\n快递柜全满，只能放驿站，结果驿站六点半就关门，我下课赶过去刚好关灯\n#快递', 42, '2026-10-01 22:26:28', 506, 35, 1, 8, 13, 0, '0', NULL),
(267, '这个菜千万别点，在线等', '新窗口今天排了二十分钟，主要现做比较慢，味道对得起等待\n三楼新开了一个窗口，卖砂锅和炒饭，今天试了砂锅饭，量足味道也还行\n那个新出的凉拌菜别点，醋放太多，吃两口就腻 #新菜', 81, '2026-10-02 00:15:10', 56, 2, 1, 2, 0, 0, '0', NULL),
(268, '夜跑第一天，在线等', '坚持一个月，体重掉了三斤，睡眠好了很多，这个收益比想象中大\n建议买双正经跑鞋，我用板鞋跑了两周，脚底板疼得下不了楼\n跑步确实会上瘾，一天不跑就难受，但膝盖也开始提醒我别太猛', 77, '2026-10-02 08:52:47', 179, 18, 1, 20, 1, 0, '0', NULL),
(269, '谁把猫抱走了，随便聊聊', '提醒一下，别喂太咸的东西，上次有人喂火腿肠，猫拉了两天肚子\n我买了一小袋猫粮，结果引来四只，最后那只橘的吃最多，还打我\n宿舍楼下那只狸花今天蹲在窗台上晒太阳，我蹲下来它就往我腿边蹭', 75, '2026-10-02 09:23:52', 282, 5, 1, 4, 2, 0, '0', NULL),
(270, '宿舍楼下的雨，在线等', '室友每天凌晨两点还在打游戏，键盘声一直响，我说了三次，他答应得好好的\n宿舍四个人共用一个插排，谁先插上谁有理\n昨晚下大雨，从窗户往外看，路灯把雨照得像在下雪，还挺好看', 49, '2026-10-02 16:38:38', 174, 9, 2, 0, 5, 0, '0', NULL),
(271, '无糖真的不甜，笑不活了（223）', '这周已经喝了四杯，钱包和体重都在抗议\n推荐加椰果不加珍珠，珍珠太顶，喝完一下午不想吃饭 #续命', 39, '2026-10-02 17:19:39', 340, 19, 1, 3, 4, 0, '0', NULL),
(272, '体测又要来了，在线等', '操场边上的自动售货机永远缺货，只有无糖茶，喝起来像草\n体测通知下来了，引体向上我一个都做不了，已经开始焦虑', 75, '2026-10-02 22:55:09', 91, 5, 2, 8, 2, 0, '0', NULL),
(273, '十二点的食堂，求个建议', '二楼最右边那个窗口的粉蒸肉是真的香，就是每次只剩一点点\n食堂的汤永远是温的，喝完更渴 #食堂', 84, '2026-10-03 01:50:25', 170, 1, 1, 0, 0, 0, '0', NULL),
(274, '复习不完了，人麻了', '期末周正式开始，课表上还剩四门，我一门都没复习完\n建议别通宵，第二天脑子是空的，我试过，代价很大\n复习效率最高的时候是考前两小时，其余时间都在整理桌面', 25, '2026-10-04 04:05:38', 136, 2, 2, 0, 0, 0, '0', '2026-10-04 04:41:38'),
(275, '复习进度汇报，人麻了', '自习室里大家都很安静，偶尔有人叹气，那种氛围挺压抑也挺鼓励\n最近一直在想如果没考上怎么办，家里希望我再来一年，我自己有点犹豫\n建议每天留一小时运动，不然到后期身体先垮 #自习', 19, '2026-10-04 07:51:46', 94, 5, 1, 0, 1, 0, '0', '2026-10-04 08:12:46'),
(276, '联调跑不通，有点破防', '部署到服务器之后才发现本地能跑不代表线上能跑，端口和防火墙都是坑\n前后端联调跑不通，最后发现是跨域配置写漏了一行，找了两个小时\n答辩 PPT 做完了，二十页，讲稿还没写，估计要练三四遍', 43, '2026-10-04 13:37:54', 413, 15, 1, 0, 2, 0, '0', '2026-10-04 14:05:54'),
(277, '加卤蛋还是加锅烧，笑不活了', '个人口味：卤菜粉加锅烧，酸豆角多放，辣椒少放，最后一定要加一勺卤水\n今天这碗加了锅烧和卤蛋，一共十一块，汤头够味，酸笋放得刚好 #桂林米粉', 77, '2026-10-04 14:37:51', 177, 2, 1, 0, 0, 0, '0', NULL),
(278, '洗衣房的队伍，谁懂啊', '室友每天凌晨两点还在打游戏，键盘声一直响，我说了三次，他答应得好好的\n晚上十一点准时断电，我的电脑刚跑到一半，直接黑屏，作业没保存\n宿舍四个人共用一个插排，谁先插上谁有理\n洗衣房四台机器坏了两个，剩下两个永远有人排队，我已经抱着衣服站了四十分钟', 82, '2026-10-04 16:34:10', 209, 2, 2, 0, 0, 0, '0', NULL),
(279, '七点五十的校园，有感而发（226）', '七点五十的校园很安静，只有保洁阿姨和几个和我一样狂奔的人\n今天差点迟到，进门的时候老师已经在讲第二页了，我从前门走到最后一排，全程被看着\n秋天的早上真的起不来，被子一裹就不想动，感觉床有引力', 77, '2026-10-04 21:06:46', 335, 14, 1, 4, 3, 0, '0', '2026-10-04 22:32:46'),
(280, '入耳戴久了耳朵疼，说说你们那边', '自习室用降噪耳机效果挺明显，翻书声和键盘声基本听不到\n建议先试戴，每个人耳道不一样，别人说舒服你不一定\n#耳机', 29, '2026-10-05 02:29:21', 418, 15, 1, 0, 2, 0, '0', NULL),
(281, '手机上也能玩，有感而发', '手机屏幕小，远处的人根本看不清，全靠猜\n通勤路上打一把挺解压，就是信号不稳，地铁里经常掉线', 19, '2026-10-05 07:10:35', 176, 4, 2, 7, 1, 0, '0', '2026-10-05 08:08:35'),
(282, '食堂是不是涨价了，有感而发', '中午十二点十分到食堂，队伍已经排到楼梯拐角，前面大概四十个人\n建议十一点半就去，人少菜全，就是要牺牲一节课的时间 #食堂', 39, '2026-10-05 19:24:49', 71, 0, 2, 5, 0, 0, '0', NULL),
(283, '操场晚上人真多，求个建议', '跑步别穿板鞋，我上周穿板鞋跑了三公里，脚底板疼了四天\n体测通知下来了，引体向上我一个都做不了，已经开始焦虑\n#操场', 33, '2026-10-05 19:46:33', 244, 2, 1, 0, 0, 1, '0', NULL),
(284, '考完第一门，在线等', '昨天通宵到三点，今天上课全程在飘，笔记写到一半变成了横线\n第一门考完感觉还行，选择题全靠直觉，问答题把能想到的都写了\n复习效率最高的时候是考前两小时，其余时间都在整理桌面\n建议别通宵，第二天脑子是空的，我试过，代价很大 #期末周', 71, '2026-10-07 02:42:48', 76, 2, 1, 0, 0, 0, '0', '2026-10-07 03:02:48'),
(285, '桌面终于收拾好了，真的会谢', '灯带贴在显示器后面，晚上关灯的时候氛围感确实有，就是有点晃眼\n说真的，外设对水平提升有限，但心情提升很大\n折腾了一晚，桌面终于像样了，显示器抬高一点脖子舒服很多', 69, '2026-10-07 04:08:41', 486, 31, 1, 0, 7, 0, '0', '2026-10-07 04:46:41'),
(286, '宿舍楼下的雨，说说你们那边', '晚上十一点准时断电，我的电脑刚跑到一半，直接黑屏，作业没保存\n洗衣房四台机器坏了两个，剩下两个永远有人排队，我已经抱着衣服站了四十分钟 #断电', 72, '2026-10-07 05:11:48', 280, 7, 1, 1, 0, 0, '0', '2026-10-07 05:52:48'),
(287, '四楼靠窗位又被占了，有感而发', '提醒一下，现在晚上十点半清场，别睡过头被保安叫醒\n下午两点去图书馆，四楼靠窗的位置全没了，只剩墙角一个没插座的位置\n我一般坐三楼，人少，缺点是空调太冷，得带件外套\n#图书馆', 24, '2026-10-07 05:20:57', 47, 3, 1, 0, 1, 0, '0', '2026-10-07 05:45:57'),
(288, '这局纯靠自己，在线等', '建议找固定队友，随机匹配太考验心态\n我死了之后他在旁边舔包舔了半分钟，最后被人家一枪带走，我也没觉得可惜\n开局他就把唯一的医疗包拿走了，中途还一直喊我给他掩护\n双排的时候他全程在聊别的，报点报错两次，我直接闭麦\n#开黑', 23, '2026-10-07 06:15:23', 285, 5, 1, 2, 1, 0, '0', NULL),
(289, '面试被问懵了，真的会谢', '面试被问到项目里为什么用 Redis，我讲了一堆缓存，他说那不加行不行，我卡住了\n建议面试前把项目里每个技术选型的原因想清楚，这个比背题重要\n#面试', 83, '2026-10-07 15:27:23', 253, 5, 1, 0, 0, 0, '0', '2026-10-07 16:10:23'),
(290, '桂林米粉哪家强，谁懂啊', '最近涨了一块，量倒是没变，也能接受\n学校后门那家我吃了两年，老板记得我不要葱，加汤的时候会多给一勺 #早餐', 64, '2026-10-07 19:24:43', 78, 2, 1, 0, 0, 0, '0', '2026-10-07 19:26:43'),
(291, '寄快递被收了十二块，人麻了', '双十一前后建议错峰，晚上九点去人最少，就是得摸黑找箱子\n快递柜全满，只能放驿站，结果驿站六点半就关门，我下课赶过去刚好关灯\n#校园日常', 46, '2026-10-07 21:54:06', 296, 6, 1, 9, 1, 0, '0', '2026-10-07 22:11:06'),
(292, '早八人今天的命是闹钟给的，有点破防', '闹钟从六点四十响到七点十分，我才爬起来，刷牙的时候还在想要不要装病\n早八最痛苦的不是上课，是要在前一晚十二点前睡着\n今天差点迟到，进门的时候老师已经在讲第二页了，我从前门走到最后一排，全程被看着\n#校园日常', 57, '2026-10-08 04:39:28', 385, 14, 2, 0, 2, 0, '0', '2026-10-08 05:07:28'),
(293, '食堂排队排到楼梯口，真的会谢', '中午十二点十分到食堂，队伍已经排到楼梯拐角，前面大概四十个人\n阿姨给我的肉明显比别人少，我怀疑是看我不顺眼，但我没说\n今天打了三个菜一共十四块，感觉比上学期贵了两块，不知道是不是我记错', 87, '2026-10-08 05:34:03', 186, 6, 2, 0, 1, 0, '0', NULL),
(294, '遇到这种队友怎么办，随便聊聊', '建议找固定队友，随机匹配太考验心态\n双排的时候他全程在聊别的，报点报错两次，我直接闭麦\n最后我一个人守住了，队友在语音里一句“哥牛”，我气就消了一半\n#开黑', 77, '2026-10-08 07:50:30', 271, 6, 1, 0, 2, 0, '0', NULL),
(295, '入耳戴久了耳朵疼，谁懂啊', '自习室用降噪耳机效果挺明显，翻书声和键盘声基本听不到\n预算两百以内，主要通勤和自习用，纠结入耳还是头戴\n头戴隔音好但夏天闷，入耳方便但戴久了耳朵疼，各有各的问题 #降噪', 87, '2026-10-08 17:34:48', 174, 0, 1, 0, 0, 0, '0', NULL),
(296, '开学前买了电脑，笑不活了', '写代码其实不需要太高的配置，内存加到十六G比什么都管用\n预算五千左右，主要写代码和看视频，偶尔打游戏，在纠结轻薄本还是游戏本\n看了几款，同价位游戏本显卡好但重，轻薄本续航好但散热差，很难两全\n别信“全新未拆”的低价，八成是翻新，这个坑我踩过', 24, '2026-10-08 18:56:06', 53, 5, 2, 4, 1, 0, '0', NULL),
(297, '宿舍网又卡了，先记下来', '打这种需要反应的游戏，延迟比配置重要，我算是体会到了\n建议错峰，晚上十一点之后反而稳，可能是因为大家都去睡了\n晚上八点到十点，宿舍网必卡，延迟从三十跳到一百五，人物走两步退一步', 95, '2026-10-08 20:55:40', 280, 14, 1, 0, 4, 0, '0', '2026-10-08 21:37:40'),
(298, '复习进度汇报，记录一下', '每天六点半起，晚上十一点回，中间有效学习时间大概七个小时，剩下都在走神\n自习室里大家都很安静，偶尔有人叹气，那种氛围挺压抑也挺鼓励\n建议每天留一小时运动，不然到后期身体先垮', 19, '2026-10-09 05:30:39', 167, 2, 1, 3, 1, 0, '0', '2026-10-09 06:09:39'),
(299, '晚上操场跑步，有感而发', '跑步确实会上瘾，一天不跑就难受，但膝盖也开始提醒我别太猛\n建议买双正经跑鞋，我用板鞋跑了两周，脚底板疼得下不了楼\n#夜跑', 82, '2026-10-09 14:09:09', 81, 5, 2, 3, 0, 0, '0', NULL),
(300, '室友的作息我真的受不了，有感而发', '洗衣房四台机器坏了两个，剩下两个永远有人排队，我已经抱着衣服站了四十分钟\n宿舍四个人共用一个插排，谁先插上谁有理\n#断电', 89, '2026-10-09 17:44:39', 59, 2, 2, 5, 0, 0, '0', NULL),
(301, '潮湿到怀疑人生，随便聊聊', '雨从早上一直下到晚上，鞋全湿了，晾在窗边一晚上没干\n回南天最难受，墙壁出水，衣服晾三天还是潮的，整个人也跟着发霉\n#天气', 55, '2026-10-09 18:31:48', 245, 7, 2, 9, 0, 0, '0', NULL),
(302, '开黑遇到奇葩，有感而发', '最后我一个人守住了，队友在语音里一句“哥牛”，我气就消了一半\n开局他就把唯一的医疗包拿走了，中途还一直喊我给他掩护\n这游戏真的需要沟通，但有些人的沟通就是指挥别人 #队友', 72, '2026-10-10 04:53:59', 77, 3, 1, 3, 0, 0, '0', '2026-10-10 05:04:59'),
(303, '这网速真的没救，谁懂啊', '建议错峰，晚上十一点之后反而稳，可能是因为大家都去睡了\n断线重连三次，第四次直接被判挂机，信誉分掉了不少\n晚上八点到十点，宿舍网必卡，延迟从三十跳到一百五，人物走两步退一步\n#延迟', 32, '2026-10-10 06:38:52', 181, 2, 2, 0, 0, 0, '0', NULL),
(304, '四级又没过，有点破防', '背单词坚持三十天，每天五十个，忘掉的比记住的多\n这次考前做了五套真题，感觉比上次稳，希望能过\n#四六级', 56, '2026-10-10 08:45:18', 225, 2, 2, 0, 1, 0, '0', '2026-10-10 09:15:18'),
(305, '半夜饿了，在线等', '凌晨一点去楼下便利店，只有关东煮和泡面，收银小哥在打瞌睡\n同样的水便利店比超市贵一块五，但胜在近，半夜也只能认了\n半夜饿了不想出门，翻遍宿舍只有一包泡面和一袋饼干\n#便利店', 44, '2026-10-10 21:09:01', 69, 4, 2, 3, 1, 0, '0', '2026-10-10 22:20:01'),
(306, '室友的作息我真的受不了，随便聊聊', '昨晚下大雨，从窗户往外看，路灯把雨照得像在下雪，还挺好看\n洗衣房四台机器坏了两个，剩下两个永远有人排队，我已经抱着衣服站了四十分钟 #断电', 87, '2026-10-10 22:20:55', 208, 5, 2, 7, 0, 0, '0', NULL),
(307, '无糖真的不甜，谁懂啊', '这周已经喝了四杯，钱包和体重都在抗议\n推荐加椰果不加珍珠，珍珠太顶，喝完一下午不想吃饭\n我一般点三分糖去冰，甜度刚好，全糖真的齁\n校门口那家新店，第二杯半价，排了半个小时，喝完觉得不太值\n#续命', 69, '2026-10-11 07:21:33', 321, 56, 1, 7, 13, 0, '0', NULL),
(308, '换了新鼠标垫，人麻了', '这套加起来花了不到六百，键盘是二手的，鼠标垫打折买的，性价比还行\n说真的，外设对水平提升有限，但心情提升很大\n灯带贴在显示器后面，晚上关灯的时候氛围感确实有，就是有点晃眼', 77, '2026-10-12 00:39:59', 155, 3, 1, 16, 0, 0, '0', NULL),
(309, '面试被问懵了，有感而发', '建议面试前把项目里每个技术选型的原因想清楚，这个比背题重要\n面试被问到项目里为什么用 Redis，我讲了一堆缓存，他说那不加行不行，我卡住了\n八股文真的背不完，昨天背的今天忘，感觉在跟自己对抗\n二面挂在场景题上，问我并发下怎么保证幂等，我只答了一半', 69, '2026-10-12 06:34:58', 280, 2, 1, 1, 0, 0, '0', NULL),
(310, '复习不完了，有点破防（273）', '老师说的重点和大家整理的重点完全不是一个东西，现在有五个版本在群里流传\n复习效率最高的时候是考前两小时，其余时间都在整理桌面\n昨天通宵到三点，今天上课全程在飘，笔记写到一半变成了横线', 72, '2026-10-12 07:04:01', 90, 1, 1, 18, 0, 0, '0', NULL),
(311, '手游手感真不行，有点破防', '建议配个散热背夹，几十块钱，效果比想象中好\n躺床上打了两小时，手腕酸得不行，还是得坐着玩\n手机屏幕小，远处的人根本看不清，全靠猜 #通勤', 69, '2026-10-12 14:56:29', 183, 2, 2, 0, 1, 0, '0', NULL),
(312, '便利店的东西真贵，说说你们那边', '同样的水便利店比超市贵一块五，但胜在近，半夜也只能认了\n换老板之后关东煮味道变了，汤淡了不少，我去得少了\n#夜宵', 82, '2026-10-12 19:04:13', 225, 1, 2, 0, 0, 0, '0', NULL),
(313, '体测又要来了，有感而发', '打球的时候踩到别人脚，脚踝肿了一圈，冰敷完还是很疼，明天估计得去医院\n坚持晨跑第五天，今天早上有雾，跑道尽头看不太清，跑起来倒挺舒服\n跑步别穿板鞋，我上周穿板鞋跑了三公里，脚底板疼了四天\n体测通知下来了，引体向上我一个都做不了，已经开始焦虑 #操场', 78, '2026-10-13 06:42:36', 94, 2, 1, 0, 2, 0, '0', NULL),
(314, '打饭阿姨的手到底抖不抖，有点破防', '食堂的汤永远是温的，喝完更渴\n建议十一点半就去，人少菜全，就是要牺牲一节课的时间', 23, '2026-10-13 06:46:05', 115, 0, 1, 0, 0, 0, '0', NULL),
(315, '跑道上的雾，记录一下', '坚持晨跑第五天，今天早上有雾，跑道尽头看不太清，跑起来倒挺舒服\n打球的时候踩到别人脚，脚踝肿了一圈，冰敷完还是很疼，明天估计得去医院\n晚上八点的操场全是人，跑道内圈被散步的占了，跑快一点就得一直绕', 52, '2026-10-13 21:46:06', 98, 0, 2, 0, 0, 0, '0', '2026-10-13 22:42:06'),
(316, '四级考试经验，谁懂啊', '六级听力像在放rap，语速快还带口音，我只能抓关键词\n这次考前做了五套真题，感觉比上次稳，希望能过', 18, '2026-10-14 01:00:25', 355, 10, 1, 0, 2, 0, '0', NULL),
(317, '操场边上的天空，记录一下', '手机拍出来比肉眼差远了，颜色压得很平，凑合看\n沿着操场外圈走了一圈，风挺凉，穿短袖已经有点顶不住\n这个点最适合发呆，什么都不想干，也不想回宿舍\n#晚霞', 75, '2026-10-14 18:38:10', 485, 23, 2, 7, 6, 0, '1', NULL),
(318, '宿舍楼下那只狸花，有感而发', '提醒一下，别喂太咸的东西，上次有人喂火腿肠，猫拉了两天肚子\n宿舍楼下那只狸花今天蹲在窗台上晒太阳，我蹲下来它就往我腿边蹭', 81, '2026-10-14 19:40:47', 144, 6, 1, 0, 0, 0, '0', '2026-10-14 19:41:47'),
(319, '宿舍楼下那只狸花，谁懂啊（348）', '有同学给它搭了个纸箱窝，第二天被人扔了，气得在群里骂了半小时\n它今天又在我书包上睡了一觉，毛沾了一书包，我也没舍得赶\n这只猫耳朵上有个缺口，估计以前打过架，现在混得挺开，谁给吃的跟谁走\n提醒一下，别喂太咸的东西，上次有人喂火腿肠，猫拉了两天肚子 #撸猫', 42, '2026-10-15 05:45:33', 102, 2, 1, 14, 1, 1, '0', '2026-10-15 07:04:33'),
(320, '米粉又涨价了，笑不活了', '今天这碗加了锅烧和卤蛋，一共十一块，汤头够味，酸笋放得刚好\n学校后门那家我吃了两年，老板记得我不要葱，加汤的时候会多给一勺\n最近涨了一块，量倒是没变，也能接受\n#桂林米粉', 77, '2026-10-15 07:15:12', 148, 9, 2, 0, 3, 0, '0', NULL),
(321, '这个续航真顶，有点破防', '旧手机留着当备用机，装个卡当热点，也算物尽其用\n买之前先去实体店摸一下，手感和重量网上看不出来\n新机续航确实好，中度使用能撑一天半，充电也快，半小时到七成\n#手机', 25, '2026-10-15 12:27:56', 281, 3, 1, 2, 1, 0, '0', NULL),
(322, '键帽换了之后，真的会谢', '宿舍里建议红轴或者静音轴，青轴真的会得罪人\n从薄膜换到机械，第一天打字速度反而变慢了，一周之后才习惯\n青轴声音太大，室友已经抗议两次，我准备换静音轴\n换了套键帽，手感没变多少，但看着舒服，这钱花得有点虚 #键盘', 69, '2026-10-16 17:03:30', 101, 2, 2, 0, 1, 0, '0', NULL),
(323, '复习不完了，先记下来', '期末周正式开始，课表上还剩四门，我一门都没复习完\n老师说的重点和大家整理的重点完全不是一个东西，现在有五个版本在群里流传 #期末周', 72, '2026-10-16 19:42:30', 258, 6, 1, 5, 1, 0, '0', NULL),
(324, '抢座实录，有感而发', '今天硬坐了两个小时，效率还行，至少把昨天的实验报告写完了\n提醒一下，现在晚上十点半清场，别睡过头被保安叫醒\n下午两点去图书馆，四楼靠窗的位置全没了，只剩墙角一个没插座的位置\n#图书馆', 69, '2026-10-17 00:33:28', 332, 3, 2, 3, 0, 0, '0', NULL),
(325, '课设终于跑起来了，求个建议', '拆分微服务的时候最麻烦的是用户信息，内容服务要调用户服务，还要处理降级\n课设终于跑起来了，五个服务加网关，启动顺序错了就各种 503，折腾了一晚上\n建议早点开始，最后一周才开始的话基本是在赌运气', 94, '2026-10-17 03:01:43', 194, 5, 1, 2, 0, 1, '0', '2026-10-17 03:35:43'),
(326, '耳机求推荐，人麻了', '预算两百以内，主要通勤和自习用，纠结入耳还是头戴\n自习室用降噪耳机效果挺明显，翻书声和键盘声基本听不到\n宿舍里耳机是必需品，不然你会听到所有你想不到的声音 #耳机', 77, '2026-10-17 07:20:43', 80, 0, 1, 10, 0, 0, '0', NULL),
(327, '课设终于跑起来了，有感而发', '建议早点开始，最后一周才开始的话基本是在赌运气\n课设终于跑起来了，五个服务加网关，启动顺序错了就各种 503，折腾了一晚上', 77, '2026-10-18 00:40:58', 231, 0, 1, 0, 0, 0, '0', NULL),
(328, '菜鸟驿站的阿姨记住了我，笑不活了', '驿站阿姨已经认识我了，看到我就直接把我那个箱子拎出来，效率高得吓人\n下课去快递站，前面排了三十多个人，队伍拐了两个弯 #校园日常', 72, '2026-10-18 05:13:15', 69, 3, 2, 0, 1, 0, '0', NULL),
(329, '排位又连跪，谁懂啊', '刚刚那把在最后三十秒被人从背后偷了，我全程没听到脚步，回放看了三遍\n新手别急着冲，先把地图记熟，不然你会像我一样在出生点转圈\n#排位', 80, '2026-10-18 07:31:05', 174, 4, 1, 0, 1, 0, '0', '2026-10-18 08:07:05'),
(330, '课设终于跑起来了，真的会谢', '答辩 PPT 做完了，二十页，讲稿还没写，估计要练三四遍\n前后端联调跑不通，最后发现是跨域配置写漏了一行，找了两个小时', 34, '2026-10-18 09:13:39', 43, 2, 2, 0, 0, 0, '0', '2026-10-18 10:11:39'),
(331, '二楼窗口的粉蒸肉，求个建议', '建议十一点半就去，人少菜全，就是要牺牲一节课的时间\n食堂的汤永远是温的，喝完更渴\n今天打了三个菜一共十四块，感觉比上学期贵了两块，不知道是不是我记错\n中午十二点十分到食堂，队伍已经排到楼梯拐角，前面大概四十个人\n#食堂', 65, '2026-10-18 18:17:23', 39, 1, 1, 0, 1, 0, '0', NULL),
(332, '自习到闭馆，笑不活了', '占座的人一半不在，桌上堆着书和水杯，人不知道去哪了\n闭馆音乐一响，整层楼同时开始收东西，那场面挺壮观\n下午两点去图书馆，四楼靠窗的位置全没了，只剩墙角一个没插座的位置\n#图书馆', 40, '2026-10-18 21:50:54', 40, 1, 2, 4, 0, 0, '0', '2026-10-18 23:08:54'),
(333, '宿舍楼下那只狸花，真的会谢', '这只猫耳朵上有个缺口，估计以前打过架，现在混得挺开，谁给吃的跟谁走\n提醒一下，别喂太咸的东西，上次有人喂火腿肠，猫拉了两天肚子 #撸猫', 38, '2026-10-19 02:04:47', 273, 23, 1, 0, 3, 1, '0', '2026-10-19 02:46:47'),
(334, '晨跑第五天，有点破防', '操场边上的自动售货机永远缺货，只有无糖茶，喝起来像草\n打球的时候踩到别人脚，脚踝肿了一圈，冰敷完还是很疼，明天估计得去医院\n跑步别穿板鞋，我上周穿板鞋跑了三公里，脚底板疼了四天', 19, '2026-10-19 06:17:29', 183, 1, 1, 0, 0, 1, '0', '2026-10-19 06:21:29'),
(335, '开学前买了电脑，人麻了', '别信“全新未拆”的低价，八成是翻新，这个坑我踩过\n预算五千左右，主要写代码和看视频，偶尔打游戏，在纠结轻薄本还是游戏本\n最后买了轻薄本，重量一点三公斤，通勤背着不累，就是风扇一开声音大\n#选购', 24, '2026-10-19 21:45:53', 206, 4, 1, 6, 2, 0, '0', '2026-10-19 22:57:53'),
(336, '食堂是不是涨价了，求个建议', '二楼最右边那个窗口的粉蒸肉是真的香，就是每次只剩一点点\n今天打了三个菜一共十四块，感觉比上学期贵了两块，不知道是不是我记错 #食堂', 23, '2026-10-20 01:19:58', 135, 0, 2, 6, 0, 0, '0', NULL),
(337, '桌面终于收拾好了，随便聊聊', '折腾了一晚，桌面终于像样了，显示器抬高一点脖子舒服很多\n说真的，外设对水平提升有限，但心情提升很大\n灯带贴在显示器后面，晚上关灯的时候氛围感确实有，就是有点晃眼\n这套加起来花了不到六百，键盘是二手的，鼠标垫打折买的，性价比还行 #外设', 52, '2026-10-20 17:17:25', 424, 15, 1, 0, 3, 0, '0', '2026-10-20 18:16:25'),
(338, '夜跑第一天，有点破防', '夜跑第一天，跑了三公里，配速七分半，腿有点酸但心情很好\n跑完顺手吃了个夜宵，等于白跑，这个循环我已经持续两周', 69, '2026-10-20 21:16:34', 36, 0, 2, 0, 0, 0, '0', NULL),
(339, '复习不完了，在线等', '第一门考完感觉还行，选择题全靠直觉，问答题把能想到的都写了\n老师说的重点和大家整理的重点完全不是一个东西，现在有五个版本在群里流传\n建议别通宵，第二天脑子是空的，我试过，代价很大\n期末周正式开始，课表上还剩四门，我一门都没复习完 #期末周', 87, '2026-10-20 21:46:36', 120, 4, 1, 9, 1, 0, '0', NULL),
(340, '教学楼后面的落日，有感而发', '手机拍出来比肉眼差远了，颜色压得很平，凑合看\n梧桐叶开始黄了，路灯一亮，地上全是碎影子\n傍晚六点多从教学楼出来，整片天是橙红过渡到紫，我站着看了五分钟才想起拍照\n拍了十几张，只有这张勉强能发，其他全糊了 #随手拍', 70, '2026-10-21 01:38:47', 188, 7, 1, 0, 2, 0, '0', NULL),
(341, '八股文背不完，随便聊聊', '二面挂在场景题上，问我并发下怎么保证幂等，我只答了一半\n面试官挺耐心，我答错的地方他会引导，聊完反而学到东西 #面试', 89, '2026-10-21 02:00:56', 145, 0, 1, 4, 0, 0, '0', '2026-10-21 02:43:56'),
(342, '今天的晚霞，随便聊聊', '沿着操场外圈走了一圈，风挺凉，穿短袖已经有点顶不住\n傍晚六点多从教学楼出来，整片天是橙红过渡到紫，我站着看了五分钟才想起拍照', 52, '2026-10-21 04:26:46', 302, 4, 1, 19, 0, 0, '0', '2026-10-21 05:18:46'),
(343, '换了把键盘，谁懂啊', '宿舍里建议红轴或者静音轴，青轴真的会得罪人\n同样的轴体，不同键帽高度手感差别挺明显，这个之前完全没想过', 43, '2026-10-21 23:51:08', 281, 1, 1, 5, 0, 0, '0', NULL),
(344, '微服务拆分踩坑，人麻了', '部署到服务器之后才发现本地能跑不代表线上能跑，端口和防火墙都是坑\n答辩 PPT 做完了，二十页，讲稿还没写，估计要练三四遍\n拆分微服务的时候最麻烦的是用户信息，内容服务要调用户服务，还要处理降级\n课设终于跑起来了，五个服务加网关，启动顺序错了就各种 503，折腾了一晚上', 55, '2026-10-22 00:21:55', 70, 4, 2, 0, 0, 0, '0', NULL),
(345, '我们宿舍的绿萝活下来了，记录一下', '宿舍四个人共用一个插排，谁先插上谁有理\n隔壁宿舍搬走了，留下一股泡面味，三天没散', 54, '2026-10-22 02:37:38', 345, 12, 2, 2, 6, 0, '0', '2026-10-22 03:17:38'),
(346, '图书馆四楼又满了，有点破防', '闭馆音乐一响，整层楼同时开始收东西，那场面挺壮观\n今天硬坐了两个小时，效率还行，至少把昨天的实验报告写完了\n占座的人一半不在，桌上堆着书和水杯，人不知道去哪了 #自习', 54, '2026-10-22 07:07:08', 349, 8, 2, 0, 0, 0, '0', '2026-10-22 07:11:08'),
(347, '通关二十小时，随便聊聊', '这游戏的解谜设计挺讲究，卡了我三次，每次想通都挺爽\n断断续续玩了二十多个小时，昨晚终于通关，结局那段我看了两遍\n#单机游戏', 19, '2026-10-22 09:00:28', 161, 8, 2, 0, 1, 0, '0', NULL),
(348, '延迟一百二怎么玩，在线等', '建议错峰，晚上十一点之后反而稳，可能是因为大家都去睡了\n打这种需要反应的游戏，延迟比配置重要，我算是体会到了 #校园网', 69, '2026-10-22 21:49:27', 110, 7, 1, 3, 2, 0, '0', NULL),
(349, '硅脂换了之后，说说你们那边', '加了一条内存，从八G到十六G，开几个网页终于不卡了\n工具一套三十块，比送修划算，前提是你敢动手\n换硅脂要注意别涂太多，我第一次涂多了，温度反而高了两度', 77, '2026-10-22 23:33:57', 86, 0, 2, 0, 0, 0, '0', NULL),
(350, '宿舍楼下那只狸花，说说你们那边', '提醒一下，别喂太咸的东西，上次有人喂火腿肠，猫拉了两天肚子\n它今天又在我书包上睡了一觉，毛沾了一书包，我也没舍得赶\n#校园猫', 72, '2026-10-23 06:19:17', 284, 2, 2, 6, 0, 0, '0', NULL),
(351, '食堂是不是涨价了，人麻了', '建议十一点半就去，人少菜全，就是要牺牲一节课的时间\n阿姨给我的肉明显比别人少，我怀疑是看我不顺眼，但我没说 #食堂', 39, '2026-10-23 09:07:14', 312, 6, 1, 13, 3, 0, '0', NULL),
(352, '宿舍必备耳机，笑不活了', '预算两百以内，主要通勤和自习用，纠结入耳还是头戴\n头戴隔音好但夏天闷，入耳方便但戴久了耳朵疼，各有各的问题\n自习室用降噪耳机效果挺明显，翻书声和键盘声基本听不到\n#耳机', 31, '2026-10-23 20:32:23', 95, 7, 1, 3, 0, 0, '0', '2026-10-23 21:42:23'),
(353, '早八教室的第一排，有点破防', '闹钟从六点四十响到七点十分，我才爬起来，刷牙的时候还在想要不要装病\n第一排永远没人坐，我坐了一次，被点名回答了三个问题', 39, '2026-10-24 05:56:44', 224, 11, 1, 0, 5, 0, '0', NULL),
(354, '四楼靠窗位又被占了，笑不活了（383）', '占座的人一半不在，桌上堆着书和水杯，人不知道去哪了\n闭馆音乐一响，整层楼同时开始收东西，那场面挺壮观\n下午两点去图书馆，四楼靠窗的位置全没了，只剩墙角一个没插座的位置', 57, '2026-10-24 08:25:11', 112, 1, 1, 0, 0, 0, '0', '2026-10-24 09:55:11'),
(355, '教学楼后面的小猫，有点破防', '宿舍楼下那只狸花今天蹲在窗台上晒太阳，我蹲下来它就往我腿边蹭\n我买了一小袋猫粮，结果引来四只，最后那只橘的吃最多，还打我\n它今天又在我书包上睡了一觉，毛沾了一书包，我也没舍得赶 #撸猫', 81, '2026-10-24 09:01:48', 568, 30, 1, 0, 4, 0, '0', NULL),
(356, '面试官人挺好，有感而发', '二面挂在场景题上，问我并发下怎么保证幂等，我只答了一半\n八股文真的背不完，昨天背的今天忘，感觉在跟自己对抗\n一面感觉一般，手撕代码写出来了但边界没处理好，居然过了', 77, '2026-10-24 09:17:36', 183, 3, 1, 0, 1, 0, '0', NULL),
(357, '菜鸟驿站的阿姨记住了我，谁懂啊', '快递柜全满，只能放驿站，结果驿站六点半就关门，我下课赶过去刚好关灯\n双十一前后建议错峰，晚上九点去人最少，就是得摸黑找箱子', 54, '2026-10-24 09:19:02', 309, 3, 1, 16, 2, 0, '1', '2026-10-24 09:34:02'),
(358, '图书馆四楼又满了，有点破防（330）', '闭馆音乐一响，整层楼同时开始收东西，那场面挺壮观\n占座的人一半不在，桌上堆着书和水杯，人不知道去哪了\n我一般坐三楼，人少，缺点是空调太冷，得带件外套 #自习', 55, '2026-10-25 02:48:12', 290, 6, 1, 3, 0, 0, '0', NULL),
(359, '今天降温了，人麻了', '秋天来了，梧桐叶开始黄，晚上不开风扇也能睡着\n雨从早上一直下到晚上，鞋全湿了，晾在窗边一晚上没干\n提醒一下，这个季节容易感冒，宿舍里已经有两个人中招', 25, '2026-10-25 07:04:58', 334, 7, 1, 0, 2, 0, '0', NULL),
(360, '二楼窗口的粉蒸肉，说说你们那边', '中午十二点十分到食堂，队伍已经排到楼梯拐角，前面大概四十个人\n阿姨给我的肉明显比别人少，我怀疑是看我不顺眼，但我没说\n食堂的汤永远是温的，喝完更渴', 63, '2026-10-25 08:31:11', 264, 2, 1, 9, 0, 0, '0', '2026-10-25 09:38:11'),
(361, '手机上也能玩，随便聊聊', '躺床上打了两小时，手腕酸得不行，还是得坐着玩\n建议配个散热背夹，几十块钱，效果比想象中好\n手机上操作确实别扭，瞄准全靠手指，打了两把就放弃了\n手机屏幕小，远处的人根本看不清，全靠猜 #通勤', 54, '2026-10-25 21:29:26', 564, 59, 1, 0, 19, 0, '0', '2026-10-25 22:13:26'),
(362, '无糖真的不甜，笑不活了', '奶茶这东西，喝的时候快乐，喝完有点后悔，第二天还是想喝\n推荐加椰果不加珍珠，珍珠太顶，喝完一下午不想吃饭\n无糖选项其实是少糖，喝起来还是有甜味，不过热量确实低一些 #续命', 19, '2026-10-25 22:20:52', 130, 12, 2, 0, 4, 0, '0', NULL),
(363, '今天又喂了猫，先记下来', '宿舍楼下那只狸花今天蹲在窗台上晒太阳，我蹲下来它就往我腿边蹭\n它今天又在我书包上睡了一觉，毛沾了一书包，我也没舍得赶', 36, '2026-10-25 23:15:03', 186, 0, 2, 0, 0, 0, '1', '2026-10-26 00:01:03'),
(364, '七点五十的校园，笑不活了', '今天差点迟到，进门的时候老师已经在讲第二页了，我从前门走到最后一排，全程被看着\n早八最痛苦的不是上课，是要在前一晚十二点前睡着\n闹钟从六点四十响到七点十分，我才爬起来，刷牙的时候还在想要不要装病', 24, '2026-10-26 02:28:42', 137, 2, 1, 4, 0, 0, '0', NULL),
(365, '自己拆机清灰，真的会谢', '工具一套三十块，比送修划算，前提是你敢动手\n加了一条内存，从八G到十六G，开几个网页终于不卡了\n拆机前记得先断电拔电池，我第一次没拔，螺丝刀碰到主板闪了一下，吓死 #拆机', 54, '2026-10-27 00:48:13', 108, 3, 1, 48, 0, 0, '0', NULL),
(366, '跑道上的雾，说说你们那边', '操场边上的自动售货机永远缺货，只有无糖茶，喝起来像草\n坚持晨跑第五天，今天早上有雾，跑道尽头看不太清，跑起来倒挺舒服\n#夜跑', 58, '2026-10-27 03:31:36', 396, 15, 2, 1, 3, 0, '0', NULL),
(367, '四级考试经验，随便聊聊', '英语这东西停一个月就废，别指望突击\n四级建议先做真题，把题型摸熟，比背单词提分快\n这次考前做了五套真题，感觉比上次稳，希望能过\n六级听力像在放rap，语速快还带口音，我只能抓关键词\n#英语', 38, '2026-10-27 21:11:35', 299, 7, 2, 6, 4, 0, '0', '2026-10-27 21:43:35'),
(368, '课设终于跑起来了，有点破防', '建议早点开始，最后一周才开始的话基本是在赌运气\n前后端联调跑不通，最后发现是跨域配置写漏了一行，找了两个小时\n答辩 PPT 做完了，二十页，讲稿还没写，估计要练三四遍', 87, '2026-10-27 21:11:41', 328, 7, 2, 0, 1, 0, '0', NULL),
(369, '快递柜满了，笑不活了', '驿站阿姨已经认识我了，看到我就直接把我那个箱子拎出来，效率高得吓人\n下课去快递站，前面排了三十多个人，队伍拐了两个弯\n今天寄一个两公斤的件，被收了十二块，我当场沉默\n双十一前后建议错峰，晚上九点去人最少，就是得摸黑找箱子', 52, '2026-10-27 22:08:40', 143, 1, 1, 0, 1, 0, '0', NULL),
(370, '通勤两小时值得吗，先记下来', '建议实习前先把基础打牢，不然进去主要是看文档，成长很慢\n带我的师傅挺耐心，我提的问题再基础他也会讲，这点挺感激\n每天通勤来回两小时，早上六点半出门，晚上八点到宿舍，人确实有点疲\n纠结要不要继续，学校那边还有课，两边都顾着有点吃不消', 87, '2026-10-28 01:13:08', 139, 2, 2, 0, 1, 0, '0', NULL),
(371, '遇到这种队友怎么办，记录一下', '建议找固定队友，随机匹配太考验心态\n开局他就把唯一的医疗包拿走了，中途还一直喊我给他掩护', 72, '2026-10-28 04:03:14', 271, 1, 2, 0, 0, 0, '0', NULL),
(372, '早八人今天的命是闹钟给的，人麻了（285）', '早八最痛苦的不是上课，是要在前一晚十二点前睡着\n今天差点迟到，进门的时候老师已经在讲第二页了，我从前门走到最后一排，全程被看着 #早八人', 66, '2026-10-28 06:41:43', 261, 0, 1, 0, 0, 0, '0', NULL),
(373, '又迟到了，先记下来', '第一排永远没人坐，我坐了一次，被点名回答了三个问题\n闹钟从六点四十响到七点十分，我才爬起来，刷牙的时候还在想要不要装病\n七点五十的校园很安静，只有保洁阿姨和几个和我一样狂奔的人', 19, '2026-10-28 08:19:17', 23, 0, 2, 2, 0, 0, '0', NULL),
(374, '洗衣房的队伍，说说你们那边', '昨晚下大雨，从窗户往外看，路灯把雨照得像在下雪，还挺好看\n洗衣房四台机器坏了两个，剩下两个永远有人排队，我已经抱着衣服站了四十分钟 #宿舍生活', 49, '2026-10-28 17:00:16', 810, 55, 1, 0, 16, 0, '0', NULL),
(375, '凌晨的便利店，在线等', '半夜饿了不想出门，翻遍宿舍只有一包泡面和一袋饼干\n同样的水便利店比超市贵一块五，但胜在近，半夜也只能认了', 36, '2026-10-28 18:20:55', 247, 1, 1, 0, 0, 0, '0', NULL),
(376, '教学楼后面的小猫，有感而发', '我买了一小袋猫粮，结果引来四只，最后那只橘的吃最多，还打我\n宿舍楼下那只狸花今天蹲在窗台上晒太阳，我蹲下来它就往我腿边蹭', 19, '2026-10-28 21:47:17', 182, 1, 2, 5, 0, 0, '0', NULL),
(377, '旧手机还能再战，真的会谢', '用三年的旧手机终于换了，主要是电池不行，一天要充两次\n新机续航确实好，中度使用能撑一天半，充电也快，半小时到七成\n拍照比想象中好，白天没问题，晚上还是有点糊，日常够用\n#手机', 16, '2026-10-29 18:15:06', 136, 7, 2, 6, 2, 0, '0', NULL),
(378, '今天的晚霞，在线等', '这个点最适合发呆，什么都不想干，也不想回宿舍\n沿着操场外圈走了一圈，风挺凉，穿短袖已经有点顶不住', 42, '2026-10-30 09:16:54', 58, 0, 1, 0, 0, 0, '0', NULL),
(379, '今天这个菜不错，笑不活了', '三楼新开了一个窗口，卖砂锅和炒饭，今天试了砂锅饭，量足味道也还行\n隐藏吃法是打一份白饭加两块钱的蒸蛋，再要一勺免费的汤，一共不到五块\n二楼的红烧肉今天炖得很烂，就是有点咸，配米饭刚好', 87, '2026-10-30 13:44:14', 393, 25, 1, 11, 5, 0, '0', NULL),
(380, '课设终于跑起来了，在线等', '答辩 PPT 做完了，二十页，讲稿还没写，估计要练三四遍\n前后端联调跑不通，最后发现是跨域配置写漏了一行，找了两个小时', 75, '2026-10-30 20:19:06', 73, 3, 1, 5, 0, 0, '0', NULL),
(381, '考研倒计时五十天，在线等', '最近一直在想如果没考上怎么办，家里希望我再来一年，我自己有点犹豫\n建议每天留一小时运动，不然到后期身体先垮 #考研', 87, '2026-10-30 22:44:52', 276, 6, 2, 0, 2, 0, '0', NULL),
(382, '桂林米粉哪家强，说说你们那边', '个人口味：卤菜粉加锅烧，酸豆角多放，辣椒少放，最后一定要加一勺卤水\n外地朋友第一次吃可能受不了酸笋的味道，建议先少放一点', 26, '2026-10-31 00:23:12', 246, 9, 2, 0, 4, 0, '0', NULL),
(383, '教学楼后面的落日，谁懂啊', '沿着操场外圈走了一圈，风挺凉，穿短袖已经有点顶不住\n手机拍出来比肉眼差远了，颜色压得很平，凑合看\n梧桐叶开始黄了，路灯一亮，地上全是碎影子\n这个点最适合发呆，什么都不想干，也不想回宿舍', 92, '2026-10-31 09:22:13', 188, 3, 1, 0, 1, 0, '0', '2026-10-31 09:30:13'),
(384, '宿舍楼下的雨，谁懂啊', '宿舍四个人共用一个插排，谁先插上谁有理\n隔壁宿舍搬走了，留下一股泡面味，三天没散\n#断电', 42, '2026-10-31 10:33:55', 134, 2, 1, 7, 2, 0, '1', NULL),
(385, '宿舍楼下那只狸花，谁懂啊', '宿舍楼下那只狸花今天蹲在窗台上晒太阳，我蹲下来它就往我腿边蹭\n有同学给它搭了个纸箱窝，第二天被人扔了，气得在群里骂了半小时\n#撸猫', 81, '2026-10-31 20:08:41', 84, 4, 1, 5, 0, 0, '0', NULL),
(386, '硅脂换了之后，谁懂啊', '工具一套三十块，比送修划算，前提是你敢动手\n加了一条内存，从八G到十六G，开几个网页终于不卡了', 52, '2026-10-31 23:38:45', 220, 11, 1, 0, 5, 0, '0', NULL),
(387, '课设终于跑起来了，笑不活了', '拆分微服务的时候最麻烦的是用户信息，内容服务要调用户服务，还要处理降级\n课设终于跑起来了，五个服务加网关，启动顺序错了就各种 503，折腾了一晚上 #课设', 33, '2026-11-01 04:04:58', 727, 52, 2, 0, 10, 1, '0', '2026-11-01 04:24:58'),
(388, '操场边上的天空，笑不活了', '沿着操场外圈走了一圈，风挺凉，穿短袖已经有点顶不住\n手机拍出来比肉眼差远了，颜色压得很平，凑合看 #随手拍', 19, '2026-11-01 05:44:59', 152, 4, 2, 0, 1, 0, '0', '2026-11-01 05:52:59'),
(389, '终于摸到金了，有点破防', '今晚打了六把，赢了四把，手感比上周好太多，主要是换了灵敏度\n刚刚那把在最后三十秒被人从背后偷了，我全程没听到脚步，回放看了三遍 #排位', 72, '2026-11-01 21:23:26', 361, 16, 1, 17, 2, 1, '0', '2026-11-01 22:51:26'),
(390, '二手笔记本靠谱吗，谁懂啊', '二手的话建议当面验机，重点看电池循环次数和屏幕有没有暗斑\n看了几款，同价位游戏本显卡好但重，轻薄本续航好但散热差，很难两全\n写代码其实不需要太高的配置，内存加到十六G比什么都管用', 47, '2026-11-02 04:35:44', 170, 8, 1, 3, 1, 0, '0', '2026-11-02 04:38:44'),
(391, '开学前买了电脑，求个建议（238）', '最后买了轻薄本，重量一点三公斤，通勤背着不累，就是风扇一开声音大\n二手的话建议当面验机，重点看电池循环次数和屏幕有没有暗斑\n看了几款，同价位游戏本显卡好但重，轻薄本续航好但散热差，很难两全\n#选购', 61, '2026-11-02 18:38:10', 496, 35, 2, 8, 9, 0, '0', '2026-11-02 18:39:10'),
(392, '这局纯靠自己，先记下来', '双排的时候他全程在聊别的，报点报错两次，我直接闭麦\n这游戏真的需要沟通，但有些人的沟通就是指挥别人', 72, '2026-11-02 20:48:40', 386, 10, 2, 0, 3, 0, '0', NULL),
(393, '秋天来了，说说你们那边', '秋天来了，梧桐叶开始黄，晚上不开风扇也能睡着\n今天突然降温，早上穿短袖出门，中午冻得去买了一件外套\n雨从早上一直下到晚上，鞋全湿了，晾在窗边一晚上没干\n提醒一下，这个季节容易感冒，宿舍里已经有两个人中招', 19, '2026-11-02 22:06:49', 139, 2, 1, 0, 1, 0, '0', NULL),
(394, '结局有点意难平，随便聊聊', '重玩一遍才发现前面埋了很多伏笔，第一遍完全没注意\n断断续续玩了二十多个小时，昨晚终于通关，结局那段我看了两遍\n这游戏的解谜设计挺讲究，卡了我三次，每次想通都挺爽\n剧情不算新鲜，但人物写得好，最后一个镜头我愣了很久', 72, '2026-11-03 02:36:09', 382, 11, 1, 14, 4, 0, '0', NULL),
(395, '快递柜满了，有感而发', '下课去快递站，前面排了三十多个人，队伍拐了两个弯\n我的快递被别人取走了，监控看了半天，最后是隔壁宿舍拿错，箱子已经拆了\n双十一前后建议错峰，晚上九点去人最少，就是得摸黑找箱子\n驿站阿姨已经认识我了，看到我就直接把我那个箱子拎出来，效率高得吓人\n#快递', 69, '2026-11-03 03:21:36', 338, 49, 1, 0, 12, 0, '0', NULL),
(396, '简历被已读了，求个建议', '投了三十家，已读的不到十家，回信两家，心态有点崩\n建议找同学互看简历，自己看永远看不出问题\n写项目建议按“问题—做法—结果”写，别只堆技术名词，面试官一问就露\n实习经历是硬门槛，没有的话就把课设做深，至少能讲清楚', 46, '2026-11-03 06:25:40', 156, 2, 1, 12, 0, 0, '0', NULL),
(397, '手机发热严重，记录一下', '手机上操作确实别扭，瞄准全靠手指，打了两把就放弃了\n手机玩这类游戏发热很厉害，玩十分钟就烫手，还会掉帧\n建议配个散热背夹，几十块钱，效果比想象中好\n#手游', 42, '2026-11-03 23:40:14', 100, 1, 1, 0, 0, 0, '0', NULL),
(398, '延迟一百二怎么玩，求个建议', '断线重连三次，第四次直接被判挂机，信誉分掉了不少\n打这种需要反应的游戏，延迟比配置重要，我算是体会到了\n开加速器能压到六十左右，就是每个月要交钱，学生党有点心疼 #校园网', 22, '2026-11-04 01:48:16', 372, 7, 1, 1, 2, 0, '0', NULL),
(399, '简历改了第八遍，笑不活了', '建议找同学互看简历，自己看永远看不出问题\n写项目建议按“问题—做法—结果”写，别只堆技术名词，面试官一问就露\n简历改了八遍，删掉了所有“熟悉”“了解”，改成具体做过什么，看着踏实多了\n实习经历是硬门槛，没有的话就把课设做深，至少能讲清楚 #简历', 62, '2026-11-04 07:38:18', 157, 1, 1, 2, 0, 0, '0', '2026-11-04 08:58:18'),
(400, '今晚手感不错，记录一下', '今晚打了六把，赢了四把，手感比上周好太多，主要是换了灵敏度\n刚刚那把在最后三十秒被人从背后偷了，我全程没听到脚步，回放看了三遍\n新手别急着冲，先把地图记熟，不然你会像我一样在出生点转圈', 83, '2026-11-04 08:09:30', 109, 4, 2, 5, 2, 0, '0', NULL);
